7df4db99-4346-4da4-b637-5b6e698cc1dd	Implement Merge Sort	Given an array of integers `arr`, your objective is to sort the array in non-decreasing order using the **Merge Sort** algorithm. \n\nMerge Sort is a classic divide-and-conquer algorithm. It works by recursively breaking down the array into two halves until each sub-array contains a single element, and then merges these sub-arrays back together in a sorted manner.	EASY	{Sorting,"Divide and Conquer",Recursion,Algorithm}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"display": {"input": "arr = [38, 27, 43, 3, 9, 82, 10]", "output": "[3, 9, 10, 27, 38, 43, 82]"}, "compiler": {"input": "7\\n38 27 43 3 9 82 10", "output": "3 9 10 27 38 43 82"}, "explanation": "The unsorted array is sorted in non-decreasing order using the Merge Sort algorithm."}, {"display": {"input": "arr = [5, -2, 9, 5, 0]", "output": "[-2, 0, 5, 5, 9]"}, "compiler": {"input": "5\\n5 -2 9 5 0", "output": "-2 0 5 5 9"}, "explanation": "The algorithm correctly sorts an array containing negative numbers and duplicate elements."}]	\N	[{"input": "7\\n38 27 43 3 9 82 10", "output": "3 9 10 27 38 43 82"}, {"input": "5\\n5 -2 9 5 0", "output": "-2 0 5 5 9"}, {"input": "5\\n1 2 3 4 5", "output": "1 2 3 4 5"}, {"input": "5\\n5 4 3 2 1", "output": "1 2 3 4 5"}, {"input": "1\\n42", "output": "42"}]	{"JAVA": {"template": "import java.util.*;\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            int n = scanner.nextInt();\\n            int[] arr = new int[n];\\n            for (int i = 0; i < n; i++) {\\n                arr[i] = scanner.nextInt();\\n            }\\n\\n            Solution sol = new Solution();\\n            int[] result = sol.mergeSort(arr);\\n\\n            for (int i = 0; i < n; i++) {\\n                System.out.print(result[i] + (i == n - 1 ? \\"\\" : \\" \\"));\\n            }\\n            System.out.println();\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    public int[] mergeSort(int[] arr) {\\n        // Write your code here\\n        return new int[0];\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = sys.stdin.readlines()\\n        n = int(lines[0].strip())\\n        arr = list(map(int, lines[1].strip().split()))\\n        \\n        sol = Solution()\\n        result = sol.mergeSort(arr)\\n\\n        if result:\\n            print(' '.join(map(str, result)))\\n\\n    except (IOError, ValueError):\\n        pass", "userCode": "    def mergeSort(self, arr: list[int]) -> list[int]:\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const n = parseInt(lines[0], 10);\\n        const arr = lines[1].split(' ').map(Number);\\n\\n        const result = mergeSort(arr);\\n\\n        if (result) {\\n            console.log(result.join(' '));\\n        }\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {number[]} arr\\n * @return {number[]}\\n */\\nvar mergeSort = function(arr) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\npublic class Main {\\n    public static int[] mergeSort(int[] arr) {\\n        if (arr.length <= 1) {\\n            return arr;\\n        }\\n        int mid = arr.length / 2;\\n        int[] left = Arrays.copyOfRange(arr, 0, mid);\\n        int[] right = Arrays.copyOfRange(arr, mid, arr.length);\\n        return merge(mergeSort(left), mergeSort(right));\\n    }\\n\\n    public static int[] merge(int[] left, int[] right) {\\n        int[] result = new int[left.length + right.length];\\n        int i = 0, j = 0, k = 0;\\n        while (i < left.length && j < right.length) {\\n            if (left[i] <= right[j]) {\\n                result[k++] = left[i++];\\n            } else {\\n                result[k++] = right[j++];\\n            }\\n        }\\n        while (i < left.length) {\\n            result[k++] = left[i++];\\n        }\\n        while (j < right.length) {\\n            result[k++] = right[j++];\\n        }\\n        return result;\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        int[] arr = new int[n];\\n        for (int i = 0; i < n; i++) {\\n            arr[i] = scanner.nextInt();\\n        }\\n\\n        int[] sortedArr = mergeSort(arr);\\n\\n        for (int i = 0; i < sortedArr.length; i++) {\\n            System.out.print(sortedArr[i] + (i == sortedArr.length - 1 ? \\"\\" : \\" \\"));\\n        }\\n        System.out.println();\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\ndef merge_sort(arr):\\n    if len(arr) <= 1:\\n        return arr\\n    \\n    mid = len(arr) // 2\\n    left_half = arr[:mid]\\n    right_half = arr[mid:]\\n    \\n    return merge(merge_sort(left_half), merge_sort(right_half))\\n\\ndef merge(left, right):\\n    result = []\\n    i, j = 0, 0\\n    \\n    while i < len(left) and j < len(right):\\n        if left[i] <= right[j]:\\n            result.append(left[i])\\n            i += 1\\n        else:\\n            result.append(right[j])\\n            j += 1\\n            \\n    result.extend(left[i:])\\n    result.extend(right[j:])\\n    return result\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    arr = list(map(int, lines[1].strip().split()))\\n    \\n    sorted_arr = merge_sort(arr)\\n    print(' '.join(map(str, sorted_arr)))\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction mergeSort(arr) {\\n    if (arr.length <= 1) {\\n        return arr;\\n    }\\n\\n    const mid = Math.floor(arr.length / 2);\\n    const left = arr.slice(0, mid);\\n    const right = arr.slice(mid);\\n\\n    return merge(mergeSort(left), mergeSort(right));\\n}\\n\\nfunction merge(left, right) {\\n    let resultArray = [], leftIndex = 0, rightIndex = 0;\\n\\n    while (leftIndex < left.length && rightIndex < right.length) {\\n        if (left[leftIndex] < right[rightIndex]) {\\n            resultArray.push(left[leftIndex]);\\n            leftIndex++;\\n        } else {\\n            resultArray.push(right[rightIndex]);\\n            rightIndex++;\\n        }\\n    }\\n\\n    return resultArray\\n        .concat(left.slice(leftIndex))\\n        .concat(right.slice(rightIndex));\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const n = parseInt(lines[0], 10);\\n    const arr = lines[1].split(' ').map(Number);\\n\\n    const sortedArr = mergeSort(arr);\\n    console.log(sortedArr.join(' '));\\n});"}	2025-07-31 19:30:17.525	2025-07-31 19:30:17.525	["1 <= arr.length <= 5000", "-10^9 <= arr[i] <= 10^9"]	{Amazon,"Goldman Sachs",Microsoft,Oracle,Paytm,Qualcomm,Snapdeal,Adobe}	\N
39f53ce6-e048-400b-8ceb-45a67e25681b	Implement Quicksort	You are given an array of integers `arr`. Your task is to sort this array in ascending order using the **Quicksort** algorithm. \n\nQuicksort is a highly efficient, recursive, divide-and-conquer sorting algorithm. Its main steps are:\n1.  **Pick** an element from the array, called a pivot.\n2.  **Partition** the other elements into two sub-arrays, according to whether they are less than or greater than the pivot.\n3.  **Recurse**: Recursively apply the above steps to the sub-arrays.	EASY	{Sorting,"Divide and Conquer",Recursion,Algorithm,Pivot}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"display": {"input": "arr = [10, 80, 30, 90, 40, 50, 70]", "output": "[10, 30, 40, 50, 70, 80, 90]"}, "compiler": {"input": "7\\n10 80 30 90 40 50 70", "output": "10 30 40 50 70 80 90"}, "explanation": "The unsorted array is rearranged into non-decreasing order using the Quicksort algorithm."}, {"display": {"input": "arr = [9, -3, 5, 2, 6, 8, -6, 1, 3, 9]", "output": "[-6, -3, 1, 2, 3, 5, 6, 8, 9, 9]"}, "compiler": {"input": "10\\n9 -3 5 2 6 8 -6 1 3 9", "output": "-6 -3 1 2 3 5 6 8 9 9"}, "explanation": "Quicksort correctly handles arrays with negative values and duplicate elements."}]	\N	[{"input": "7\\n10 80 30 90 40 50 70", "output": "10 30 40 50 70 80 90"}, {"input": "10\\n9 -3 5 2 6 8 -6 1 3 9", "output": "-6 -3 1 2 3 5 6 8 9 9"}, {"input": "4\\n10 20 30 40", "output": "10 20 30 40"}, {"input": "4\\n40 30 20 10", "output": "10 20 30 40"}, {"input": "4\\n5 5 5 5", "output": "5 5 5 5"}]	{"JAVA": {"template": "import java.util.*;\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            int n = scanner.nextInt();\\n            int[] arr = new int[n];\\n            for (int i = 0; i < n; i++) {\\n                arr[i] = scanner.nextInt();\\n            }\\n\\n            Solution sol = new Solution();\\n            sol.quickSort(arr, 0, n - 1);\\n\\n            for (int i = 0; i < n; i++) {\\n                System.out.print(arr[i] + (i == n - 1 ? \\"\\" : \\" \\"));\\n            }\\n            System.out.println();\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    // This function takes last element as pivot, places\\n    // the pivot element at its correct position in sorted\\n    // array, and places all smaller (smaller than pivot)\\n    // to left of pivot and all greater elements to right\\n    // of pivot\\n    int partition(int arr[], int low, int high) {\\n        // Write your code here\\n        return 0;\\n    }\\n\\n    // The main function that implements QuickSort\\n    // arr[] --> Array to be sorted,\\n    // low --> Starting index,\\n    // high --> Ending index\\n    void quickSort(int arr[], int low, int high) {\\n        // Write your code here\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\n# It's recommended to increase recursion limit for deep recursion cases.\\n# sys.setrecursionlimit(10**6)\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = sys.stdin.readlines()\\n        n = int(lines[0].strip())\\n        arr = list(map(int, lines[1].strip().split()))\\n        \\n        sol = Solution()\\n        sol.quickSort(arr, 0, n - 1)\\n\\n        print(' '.join(map(str, arr)))\\n\\n    except (IOError, ValueError):\\n        pass", "userCode": "    def partition(self, arr, low, high):\\n        # write your code here\\n        pass\\n\\n    # The main function that implements QuickSort\\n    # arr[] --> Array to be sorted,\\n    # low --> Starting index,\\n    # high --> Ending index\\n    def quickSort(self, arr, low, high):\\n        # write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const n = parseInt(lines[0], 10);\\n        const arr = lines[1].split(' ').map(Number);\\n\\n        quickSort(arr, 0, n - 1);\\n\\n        console.log(arr.join(' '));\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {number[]} arr\\n * @param {number} low\\n * @param {number} high\\n */\\nfunction partition(arr, low, high) {\\n    // Write your code here\\n}\\n\\n/**\\n * @param {number[]} arr\\n * @param {number} low\\n * @param {number} high\\n */\\nfunction quickSort(arr, low, high) {\\n    // Write your code here\\n}"}}	{"JAVA": "import java.util.*;\\n\\npublic class Main {\\n\\n    public static int partition(int arr[], int low, int high) {\\n        int pivot = arr[high];\\n        int i = (low - 1); // index of smaller element\\n        for (int j = low; j < high; j++) {\\n            if (arr[j] < pivot) {\\n                i++;\\n                // swap arr[i] and arr[j]\\n                int temp = arr[i];\\n                arr[i] = arr[j];\\n                arr[j] = temp;\\n            }\\n        }\\n        // swap arr[i+1] and arr[high] (or pivot)\\n        int temp = arr[i + 1];\\n        arr[i + 1] = arr[high];\\n        arr[high] = temp;\\n        return i + 1;\\n    }\\n\\n    public static void quickSort(int arr[], int low, int high) {\\n        if (low < high) {\\n            int pi = partition(arr, low, high);\\n            quickSort(arr, low, pi - 1);\\n            quickSort(arr, pi + 1, high);\\n        }\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        int[] arr = new int[n];\\n        for (int i = 0; i < n; i++) {\\n            arr[i] = scanner.nextInt();\\n        }\\n\\n        quickSort(arr, 0, n - 1);\\n\\n        for (int i = 0; i < n; i++) {\\n            System.out.print(arr[i] + (i == n - 1 ? \\"\\" : \\" \\"));\\n        }\\n        System.out.println();\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\nsys.setrecursionlimit(5001)\\n\\ndef partition(arr, low, high):\\n    i = (low - 1)\\n    pivot = arr[high]\\n\\n    for j in range(low, high):\\n        if arr[j] < pivot:\\n            i = i + 1\\n            arr[i], arr[j] = arr[j], arr[i]\\n\\n    arr[i + 1], arr[high] = arr[high], arr[i + 1]\\n    return (i + 1)\\n\\ndef quick_sort(arr, low, high):\\n    if low < high:\\n        pi = partition(arr, low, high)\\n        quick_sort(arr, low, pi - 1)\\n        quick_sort(arr, pi + 1, high)\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    arr = list(map(int, lines[1].strip().split()))\\n    \\n    quick_sort(arr, 0, n - 1)\\n    \\n    print(' '.join(map(str, arr)))\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction partition(arr, low, high) {\\n    let pivot = arr[high];\\n    let i = low - 1;\\n\\n    for (let j = low; j < high; j++) {\\n        if (arr[j] < pivot) {\\n            i++;\\n            [arr[i], arr[j]] = [arr[j], arr[i]]; // Swap\\n        }\\n    }\\n    [arr[i + 1], arr[high]] = [arr[high], arr[i + 1]]; // Swap pivot\\n    return i + 1;\\n}\\n\\nfunction quickSort(arr, low, high) {\\n    if (low < high) {\\n        let pi = partition(arr, low, high);\\n        quickSort(arr, low, pi - 1);\\n        quickSort(arr, pi + 1, high);\\n    }\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const n = parseInt(lines[0], 10);\\n    const arr = lines[1].split(' ').map(Number);\\n\\n    quickSort(arr, 0, n - 1);\\n    console.log(arr.join(' '));\\n});"}	2025-07-31 19:30:59.128	2025-07-31 19:30:59.128