75886008-9fd4-4aea-a634-42ab7d84ee64	Inversion Count	An **inversion** in an array is a pair of indices $(i, j)$ such that $i < j$ and $A[i] > A[j]$. The inversion count for an array is the total number of inversions. It's a measure of how unsorted the array is. A sorted array has an inversion count of 0, while a reverse-sorted array has the maximum possible inversion count.\n\nGiven an array of integers `A`, your task is to calculate its inversion count.	MEDIUM	{Array,Sorting,"Divide and Conquer","Merge Sort"}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"display": {"input": "A = [2, 4, 1, 3, 5]", "output": "3"}, "compiler": {"input": "5\\n2 4 1 3 5", "output": "3"}, "explanation": "The pairs of indices (i, j) that form inversions are (1, 2) for (A[1]=4, A[2]=1), (0, 2) for (A[0]=2, A[2]=1), and (1, 3) for (A[1]=4, A[3]=3). Total inversions: 3."}, {"display": {"input": "A = [5, 4, 3, 2, 1]", "output": "10"}, "compiler": {"input": "5\\n5 4 3 2 1", "output": "10"}, "explanation": "In a reverse-sorted array, every pair of elements is an inversion. The total count is n*(n-1)/2 = 5*4/2 = 10."}]	\N	[{"input": "5\\n2 4 1 3 5", "output": "3"}, {"input": "5\\n5 4 3 2 1", "output": "10"}, {"input": "5\\n1 2 3 4 5", "output": "0"}, {"input": "4\\n8 4 2 1", "output": "6"}, {"input": "3\\n3 1 2", "output": "2"}]	{"JAVA": {"template": "import java.util.*;\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            int n = scanner.nextInt();\\n            long[] arr = new long[n];\\n            for (int i = 0; i < n; i++) {\\n                arr[i] = scanner.nextLong();\\n            }\\n\\n            Solution sol = new Solution();\\n            System.out.println(sol.inversionCount(arr, n));\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    // arr[]: Input Array\\n    // n : Size of the Array\\n    // Function to count inversions in the array.\\n    static long inversionCount(long arr[], int n) {\\n        // Your Code Here\\n        return 0;\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = sys.stdin.readlines()\\n        n = int(lines[0].strip())\\n        arr = list(map(int, lines[1].strip().split()))\\n        \\n        sol = Solution()\\n        result = sol.inversionCount(arr, n)\\n        print(result)\\n\\n    except (IOError, ValueError):\\n        pass", "userCode": "    # arr is the list of integers\\n    # n is the length of the list\\n    def inversionCount(self, arr, n):\\n        # Your Code Here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const n = parseInt(lines[0], 10);\\n        const arr = lines[1].split(' ').map(Number);\\n\\n        const result = inversionCount(arr, n);\\n        console.log(result);\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {number[]} arr\\n * @param {number} n\\n * @returns {number}\\n */\\nfunction inversionCount(arr, n) {\\n    // Write your code here\\n}"}}	{"JAVA": "import java.util.*;\\n\\npublic class Main {\\n\\n    static long mergeAndCount(long[] arr, int l, int m, int r) {\\n        long[] left = Arrays.copyOfRange(arr, l, m + 1);\\n        long[] right = Arrays.copyOfRange(arr, m + 1, r + 1);\\n\\n        long inversions = 0;\\n        int i = 0, j = 0, k = l;\\n        while (i < left.length && j < right.length) {\\n            if (left[i] <= right[j]) {\\n                arr[k++] = left[i++];\\n            } else {\\n                arr[k++] = right[j++];\\n                inversions += (m + 1) - (l + i);\\n            }\\n        }\\n        while (i < left.length) {\\n            arr[k++] = left[i++];\\n        }\\n        while (j < right.length) {\\n            arr[k++] = right[j++];\\n        }\\n        return inversions;\\n    }\\n\\n    static long mergeSortAndCount(long[] arr, int l, int r) {\\n        long count = 0;\\n        if (l < r) {\\n            int m = (l + r) / 2;\\n            count += mergeSortAndCount(arr, l, m);\\n            count += mergeSortAndCount(arr, m + 1, r);\\n            count += mergeAndCount(arr, l, m, r);\\n        }\\n        return count;\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        long[] arr = new long[n];\\n        for (int i = 0; i < n; i++) {\\n            arr[i] = scanner.nextLong();\\n        }\\n\\n        System.out.println(mergeSortAndCount(arr, 0, n - 1));\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\ndef merge_sort(arr):\\n    if len(arr) <= 1:\\n        return arr, 0\\n    \\n    mid = len(arr) // 2\\n    left, inv_left = merge_sort(arr[:mid])\\n    right, inv_right = merge_sort(arr[mid:])\\n    merged, inv_merge = merge(left, right)\\n    \\n    return merged, inv_left + inv_right + inv_merge\\n\\ndef merge(left, right):\\n    merged = []\\n    inversions = 0\\n    i, j = 0, 0\\n    \\n    while i < len(left) and j < len(right):\\n        if left[i] <= right[j]:\\n            merged.append(left[i])\\n            i += 1\\n        else:\\n            merged.append(right[j])\\n            inversions += len(left) - i\\n            j += 1\\n    \\n    merged.extend(left[i:])\\n    merged.extend(right[j:])\\n    \\n    return merged, inversions\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    arr = list(map(int, lines[1].strip().split()))\\n    \\n    _, total_inversions = merge_sort(arr)\\n    print(total_inversions)\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction mergeAndCount(arr, l, m, r) {\\n    const left = arr.slice(l, m + 1);\\n    const right = arr.slice(m + 1, r + 1);\\n\\n    let inversions = 0;\\n    let i = 0, j = 0, k = l;\\n\\n    while (i < left.length && j < right.length) {\\n        if (left[i] <= right[j]) {\\n            arr[k++] = left[i++];\\n        } else {\\n            arr[k++] = right[j++];\\n            inversions += left.length - i;\\n        }\\n    }\\n\\n    while (i < left.length) {\\n        arr[k++] = left[i++];\\n    }\\n    while (j < right.length) {\\n        arr[k++] = right[j++];\\n    }\\n\\n    return inversions;\\n}\\n\\nfunction mergeSortAndCount(arr, l, r) {\\n    let count = 0;\\n    if (l < r) {\\n        const m = Math.floor((l + r) / 2);\\n        count += mergeSortAndCount(arr, l, m);\\n        count += mergeSortAndCount(arr, m + 1, r);\\n        count += mergeAndCount(arr, l, m, r);\\n    }\\n    return count;\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const n = parseInt(lines[0], 10);\\n    const arr = lines[1].split(' ').map(Number);\\n\\n    const result = mergeSortAndCount(arr, 0, n - 1);\\n    console.log(result);\\n});"}	2025-07-31 19:31:39.974	2025-07-31 19:31:39.974	["1 <= n <= 10000", "1 <= A[i] <= 100000"]	{Adobe,Amazon,Flipkart,Microsoft,Myntra}	\N
c70b2998-d8de-4a78-8380-68f9f20c2124	Climbing Stairs	You are climbing a staircase. It takes n steps to reach the top. Each time you can either climb 1 or 2 steps. In how many distinct ways can you climb to the top?	EASY	{"Dynamic Programming",Math,Memoization}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"input": "4", "output": "5", "explanation": "There are five ways to climb to the top:\\n1. 1 step + 1 step + 1 step + 1 step\\n2. 1 step + 1 step + 2 steps\\n3. 1 step + 2 steps + 1 step\\n4. 2 steps + 1 step + 1 step\\n5. 2 steps + 2 steps"}, {"input": "3", "output": "3", "explanation": "There are three ways to climb to the top:\\n1. 1 step + 1 step + 1 step\\n2. 1 step + 2 steps\\n3. 2 steps + 1 step"}, {"input": "2", "output": "2", "explanation": "There are two ways to climb to the top:\\n1. 1 step + 1 step\\n2. 2 steps"}]	\N	[{"input": "2", "output": "2"}, {"input": "3", "output": "3"}, {"input": "4", "output": "5"}]	{"JAVA": {"template": "import java.util.Scanner;\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            if (scanner.hasNextLine()) {\\n                int n = Integer.parseInt(scanner.nextLine().trim());\\n                Main main = new Main();\\n                int result = main.climbStairs(n);\\n                System.out.println(result);\\n            }\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "    public int climbStairs(int n) {\\n        // Write your code here\\n        return 0;\\n    }"}, "PYTHON": {"template": "import sys\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == \\"__main__\\":\\n    try:\\n        n = int(sys.stdin.readline().strip())\\n        sol = Solution()\\n        result = sol.climbStairs(n)\\n        if result is not None:\\n            print(result)\\n    except (IOError, ValueError):\\n        pass", "userCode": "    def climbStairs(self, n: int) -> int:\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n  input: process.stdin,\\n  output: process.stdout,\\n  terminal: false\\n});\\n\\nrl.on('line', (line) => {\\n  try {\\n    const n = parseInt(line.trim());\\n    const result = climbStairs(n);\\n    if (result !== undefined) {\\n        console.log(result);\\n    }\\n    rl.close();\\n  } catch (e) {\\n    rl.close();\\n  }\\n});", "userCode": "/**\\n * @param {number} n\\n * @return {number}\\n */\\nvar climbStairs = function(n) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.Scanner;\\n\\nclass Main {\\n  public int climbStairs(int n) {\\n      // Base cases\\n      if (n <= 2) {\\n          return n;\\n      }\\n      \\n      // Dynamic programming approach\\n      int[] dp = new int[n + 1];\\n      dp[1] = 1;\\n      dp[2] = 2;\\n      \\n      for (int i = 3; i <= n; i++) {\\n          dp[i] = dp[i - 1] + dp[i - 2];\\n      }\\n      \\n      return dp[n];\\n      \\n      /* Alternative approach with O(1) space\\n      int a = 1; // ways to climb 1 step\\n      int b = 2; // ways to climb 2 steps\\n      \\n      for (int i = 3; i <= n; i++) {\\n          int temp = a + b;\\n          a = b;\\n          b = temp;\\n      }\\n      \\n      return n == 1 ? a : b;\\n      */\\n  }\\n  \\n  public static void main(String[] args) {\\n      Scanner scanner = new Scanner(System.in);\\n      int n = Integer.parseInt(scanner.nextLine().trim());\\n      \\n      // Use Main class instead of Solution\\n      Main main = new Main();\\n      int result = main.climbStairs(n);\\n      \\n      System.out.println(result);\\n      scanner.close();\\n  }\\n}", "PYTHON": "class Solution:\\n  def climbStairs(self, n: int) -> int:\\n      # Base cases\\n      if n <= 2:\\n          return n\\n      \\n      # Dynamic programming approach\\n      dp = [0] * (n + 1)\\n      dp[1] = 1\\n      dp[2] = 2\\n      \\n      for i in range(3, n + 1):\\n          dp[i] = dp[i - 1] + dp[i - 2]\\n      \\n      return dp[n]\\n      \\n      # Alternative approach with O(1) space\\n      # a, b = 1, 2\\n      # \\n      # for i in range(3, n + 1):\\n      #     a, b = b, a + b\\n      # \\n      # return a if n == 1 else b\\n\\n# Input parsing\\nif __name__ == \\"__main__\\":\\n  import sys\\n  \\n  # Parse input\\n  n = int(sys.stdin.readline().strip())\\n  \\n  # Solve\\n  sol = Solution()\\n  result = sol.climbStairs(n)\\n  \\n  # Print result\\n  print(result)", "JAVASCRIPT": "/**\\n    * @param {number} n\\n    * @return {number}\\n    */\\n    function climbStairs(n) {\\n    // Base cases\\n    if (n <= 2) {\\n      return n;\\n    }\\n      \\n    // Dynamic programming approach\\n    let dp = new Array(n + 1);\\n    dp[1] = 1;\\n    dp[2] = 2;\\n      \\n    for (let i = 3; i <= n; i++) {\\n      dp[i] = dp[i - 1] + dp[i - 2];\\n    }\\n      \\n    return dp[n];\\n      \\n    /* Alternative approach with O(1) space\\n    let a = 1; // ways to climb 1 step\\n    let b = 2; // ways to climb 2 steps\\n      \\n    for (let i = 3; i <= n; i++) {\\n      let temp = a + b;\\n      a = b;\\n      b = temp;\\n    }\\n      \\n    return n === 1 ? a : b;\\n    */\\n    }\\n      \\n    // Parse input and execute\\n    const readline = require('readline');\\n    const rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n    });\\n      \\n    rl.on('line', (line) => {\\n    const n = parseInt(line.trim());\\n    const result = climbStairs(n);\\n\\n    console.log(result);\\n    rl.close();\\n    });"}	2025-07-29 10:29:44.693	2025-07-31 09:38:13.57	["1 <= n <= 45", "working"]	\N	\N
