22fee55b-fbcd-45e0-b440-3d73abe37b6c	Pascal's Triangle	Given a non-negative integer `n`, your task is to generate and return the `n`-th row of Pascal's triangle. In Pascal's triangle, each number is the sum of the two numbers directly above it, with the edges of the triangle always being 1.	EASY	{Array,"Dynamic Programming",Math}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"display": {"input": "n = 4", "output": "1 3 3 1"}, "compiler": {"input": "4", "output": "1 3 3 1"}, "explanation": "The 4th row of Pascal's triangle is [1, 3, 3, 1]."}, {"display": {"input": "n = 1", "output": "1"}, "compiler": {"input": "1", "output": "1"}, "explanation": "The 1st row is simply [1]."}]	\N	[{"input": "4", "output": "1 3 3 1"}, {"input": "5", "output": "1 4 6 4 1"}, {"input": "6", "output": "1 5 10 10 5 1"}]	{"JAVA": {"template": "import java.util.*;\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            int n = Integer.parseInt(scanner.nextLine().trim());\\n            Main main = new Main();\\n            List<Integer> result = main.generateNthRow(n);\\n            for (int i = 0; i < result.size(); i++) {\\n                System.out.print(result.get(i) + (i == result.size() - 1 ? \\"\\" : \\" \\"));\\n            }\\n            System.out.println();\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "    public List<Integer> generateNthRow(int n) {\\n        // Write your code here\\n        return new ArrayList<>();\\n    }"}, "PYTHON": {"template": "import sys\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        n = int(sys.stdin.readline().strip())\\n        sol = Solution()\\n        result = sol.generateNthRow(n)\\n        if result is not None:\\n            print(' '.join(map(str, result)))\\n    except (IOError, ValueError):\\n        pass", "userCode": "    def generateNthRow(self, n: int) -> list[int]:\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n  input: process.stdin,\\n  output: process.stdout,\\n  terminal: false\\n});\\n\\nrl.on('line', (line) => {\\n    try {\\n        const n = parseInt(line.trim());\\n        const result = generateNthRow(n);\\n        if (result !== undefined) {\\n            console.log(result.join(' '));\\n        }\\n    } catch (e) {}\\n    rl.close();\\n});", "userCode": "/**\\n * @param {number} n\\n * @return {number[]}\\n */\\nvar generateNthRow = function(n) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\npublic class Main {\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = Integer.parseInt(scanner.nextLine().trim());\\n        \\n        List<Integer> row = new ArrayList<>();\\n        row.add(1);\\n        \\n        for (int i = 1; i < n; i++) {\\n            List<Integer> newRow = new ArrayList<>();\\n            newRow.add(1);\\n            for (int j = 0; j < row.size() - 1; j++) {\\n                newRow.add(row.get(j) + row.get(j + 1));\\n            }\\n            newRow.add(1);\\n            row = newRow;\\n        }\\n\\n        for (int i = 0; i < row.size(); i++) {\\n            System.out.print(row.get(i) + (i == row.size() - 1 ? \\"\\" : \\" \\"));\\n        }\\n        System.out.println();\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\ndef solve():\\n    n = int(sys.stdin.readline().strip())\\n    row = [1]\\n    for i in range(n - 1):\\n        new_row = [1]\\n        for j in range(len(row) - 1):\\n            new_row.append(row[j] + row[j+1])\\n        new_row.append(1)\\n        row = new_row\\n    print(' '.join(map(str, row)))\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nconst rl = readline.crea