\");\\n                sb.append(result.get(i).get(1));\\n                sb.append(\\",\\");\\n                sb.append(result.get(i).get(2));\\n                sb.append(\\"]\\");\\n                if (i < result.size() - 1) sb.append(\\",\\");\\n            }\\n            sb.append(\\"]\\");\\n            System.out.println(sb.toString());\\n\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "    public List<List<Integer>> findZeroSumTriplets(int[] nums) {\\n        // Write your code here\\n        return new ArrayList<>();\\n    }"}, "PYTHON": {"template": "import sys\\nimport json\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = sys.stdin.readlines()\\n        n = int(lines[0].strip())\\n        nums = [int(x) for x in lines[1].strip().split()]\\n        sol = Solution()\\n        result = sol.findZeroSumTriplets(nums)\\n        if result is not None:\\n            sorted_result = sorted([sorted(triplet) for triplet in result])\\n            print(json.dumps(sorted_result, separators=(',', ':')))\\n    except (IOError, ValueError):\\n        pass", "userCode": "    def findZeroSumTriplets(self, nums: list[int]) -> list[list[int]]:\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n  input: process.stdin,\\n  output: process.stdout,\\n  terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line)\\n    if(lines.length >= 2) {\\n        try {\\n            const nums = lines[1].split(' ').map(Number);\\n            const result = findZeroSumTriplets(nums);\\n            if (result !== undefined) {\\n                const sortedResult = result.map(t => t.sort((a,b) => a-b)).sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2]);\\n                console.log(JSON.stringify(sortedResult));\\n            }\\n        } catch (e) {}\\n        rl.close();\\n    }\\n});", "userCode": "/**\\n * @param {number[]} nums\\n * @return {number[][]}\\n */\\nvar findZeroSumTriplets = function(nums) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\npublic class Main {\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = Integer.parseInt(scanner.nextLine().trim());\\n        String[] numStrs = scanner.nextLine().trim().split(\\" \\");\\n        int[] nums = new int[n];\\n        for (int i = 0; i < n; i++) {\\n            nums[i] = Integer.parseInt(numStrs[i]);\\n        }\\n\\n        List<List<Integer>> res = new ArrayList<>();\\n        Arrays.sort(nums);\\n        for (int i = 0; i < nums.length; i++) {\\n            if (i > 0 && nums[i] == nums[i - 1]) continue;\\n            int l = i + 1, r = nums.length - 1;\\n            while (l < r) {\\n                int threeSum = nums[i] + nums[l] + nums[r];\\n                if (threeSum > 0) r--;\\n                else if (threeSum < 0) l++;\\n                else {\\n                    res.add(Arrays.asList(nums[i], nums[l], nums[r]));\\n                    l++;\\n                    while (l < r && nums[l] == nums[l - 1]) l++;\\n                }\\n            }\\n        }\\n        \\n        res.sort((a, b) -> {\\n            for (int i = 0; i < a.size(); i++) {\\n                int comp = a.get(i).compareTo(b.get(i));\\n                if (comp != 0) return comp;\\n            }\\n            return 0;\\n        });\\n\\n        StringBuilder sb = new StringBuilder();\\n        sb.append(\\"[\\");\\n        for (int i = 0; i < res.size(); i++) {\\n            sb.append(\\"[\\");\\n            sb.append(res.get(i).get(0));\\n            sb.append(\\",\\");\\n            sb.append(res.get(i).get(1));\\n            sb.append(\\",\\");\\n            sb.append(res.get(i).get(2));\\n            sb.append(\\"]\\");\\n            if (i < res.size() - 1) sb.append(\\",\\");\\n        }\\n        sb.append(\\"]\\");\\n        System.out.println(sb.toString());\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\nimport json\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    nums = [int(x) for x in lines[1].strip().split()]\\n    res = []\\n    nums.sort()\\n    for i, a in enumerate(nums):\\n        if i > 0 and a == nums[i - 1]:\\n            continue\\n        l, r = i + 1, len(nums) - 1\\n        while l < r:\\n            threeSum = a + nums[l] + nums[r]\\n            if threeSum > 0:\\n                r -= 1\\n            elif threeSum < 0:\\n                l += 1\\n            else:\\n                res.append([a, nums[l], nums[r]])\\n                l += 1\\n                while nums[l] == nums[l - 1] and l < r:\\n                    l += 1\\n    sorted_res = sorted(res)\\n    print(json.dumps(sorted_res, separators=(',', ':')))\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nconst rl = readline.createInterface({\\n  input: process.stdin,\\n  output: process.stdout,\\n  terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n    if(lines.length >= 2) {\\n        const nums = lines[1].split(' ').map(Number);\\n        const res = [];\\n        nums.sort((a, b) => a - b);\\n        for (let i = 0; i < nums.length; i++) {\\n            if (i > 0 && nums[i] === nums[i - 1]) continue;\\n            let l = i + 1, r = nums.length - 1;\\n            while (l < r) {\\n                const threeSum = nums[i] + nums[l] + nums[r];\\n                if (threeSum > 0) r--;\\n                else if (threeSum < 0) l++;\\n                else {\\n                    res.push([nums[i], nums[l], nums[r]]);\\n                    l++;\\n                    while (l < r && nums[l] === nums[l - 1]) l++;\\n                }\\n            }\\n        }\\n        const sortedResult = res.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2]);\\n        console.log(JSON.stringify(sortedResult));\\n        rl.close();\\n    }\\n});"}	2025-07-31 19:08:43.203	2025-07-31 19:08:43.203	["3 <= n <= 3000", "-10^5 <= A[i] <= 10^5"]	{Amazon,Facebook,Microsoft}	\N
