p.containsKey(complement)) {\\n                int[] result = new int[]{numMap.get(complement), i};\\n                Arrays.sort(result);\\n                System.out.println(\\"[\\" + result[0] + \\",\\" + result[1] + \\"]\\");\\n                return;\\n            }\\n            numMap.put(nums[i], i);\\n        }\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\nimport json\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    nums = [int(n) for n in lines[0].strip().split()]\\n    target = int(lines[1].strip())\\n    \\n    num_map = {}\\n    for i, num in enumerate(nums):\\n        complement = target - num\\n        if complement in num_map:\\n            print(json.dumps(sorted([num_map[complement], i]), separators=(',', ':')))\\n            return\\n        num_map[num] = i\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nconst rl = readline.createInterface({\\n  input: process.stdin,\\n  output: process.stdout,\\n  terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n    if (lines.length >= 2) {\\n        const nums = lines[0].split(' ').map(Number);\\n        const target = parseInt(lines[1].trim());\\n        \\n        const numMap = new Map();\\n        for (let i = 0; i < nums.length; i++) {\\n            const complement = target - nums[i];\\n            if (numMap.has(complement)) {\\n                const result = [numMap.get(complement), i].sort((a, b) => a - b);\\n                console.log(JSON.stringify(result));\\n                break;\\n            }\\n            numMap.set(nums[i], i);\\n        }\\n        rl.close();\\n    }\\n});"}	2025-07-31 19:10:23.02	2025-07-31 19:10:23.02	["2 <= nums.length <= 10^5", "-10^9 <= nums[i] <= 10^9", "-10^9 <= target <= 10^9"]	{Amazon,Flipkart,Google,Microsoft,"Morgan Stanley"}	\N
