[][] matrix = new int[n][m];\\n        for (int i = 0; i < n; i++) {\\n            for (int j = 0; j < m; j++) {\\n                matrix[i][j] = scanner.nextInt();\\n            }\\n        }\\n\\n        int[][] rotated = new int[m][n];\\n        for (int i = 0; i < n; i++) {\\n            for (int j = 0; j < m; j++) {\\n                rotated[j][n - 1 - i] = matrix[i][j];\\n            }\\n        }\\n\\n        for (int i = 0; i < m; i++) {\\n            for (int j = 0; j < n; j++) {\\n                System.out.print(rotated[i][j] + (j == n - 1 ? \\"\\" : \\" \\"));\\n            }\\n            System.out.println();\\n        }\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n, m = map(int, lines[0].strip().split())\\n    matrix = []\\n    for i in range(1, n + 1):\\n        row = list(map(int, lines[i].strip().split()))\\n        matrix.append(row)\\n    \\n    rotated = [[0 for _ in range(n)] for _ in range(m)]\\n    for i in range(n):\\n        for j in range(m):\\n            rotated[j][n - 1 - i] = matrix[i][j]\\n    \\n    for row in rotated:\\n        print(' '.join(map(str, row)))\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nconst rl = readline.createInterface({\\n  input: process.stdin,\\n  output: process.stdout,\\n  terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const [n, m] = lines[0].split(' ').map(Number);\\n    const matrix = [];\\n    for (let i = 1; i <= n; i++) {\\n        matrix.push(lines[i].split(' ').map(Number));\\n    }\\n\\n    const rotated = Array(m).fill(0).map(() => Array(n).fill(0));\\n    for (let i = 0; i < n; i++) {\\n        for (let j = 0; j < m; j++) {\\n            rotated[j][n - 1 - i] = matrix[i][j];\\n        }\\n    }\\n\\n    rotated.forEach(row => console.log(row.join(' ')));\\n});"}	2025-07-31 19:15:28.52	2025-07-31 19:15:28.52	