b98ba44e-f484-45f1-be59-bf2acf8a4192	Next Greater Permutation	You are given an array of integers `arr`. Your task is to implement the 'next permutation' function, which rearranges the numbers into the lexicographically next greater permutation of numbers. \n\nIf such an arrangement is not possible (i.e., the array is already in descending order), you must rearrange it as the lowest possible order (i.e., sorted in ascending order). \n\nThe replacement must be done **in-place** and use only constant extra memory. You should not use any built-in library function for finding permutations.	HARD	{Array,"Two Pointers",In-Place,Algorithm}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"display": {"input": "arr = [1, 3, 2]", "output": "[2, 1, 3]"}, "compiler": {"input": "3\\n1 3 2", "output": "2 1 3"}, "explanation": "The permutation [1, 3, 2] is greater than [1, 2, 3]. The next permutation in lexicographical order is [2, 1, 3]."}, {"display": {"input": "arr = [3, 2, 1]", "output": "[1, 2, 3]"}, "compiler": {"input": "3\\n3 2 1", "output": "1 2 3"}, "explanation": "The array is sorted in descending order, which is the largest possible permutation. Therefore, the next permutation is the smallest possible order (sorted ascending)."}, {"display": {"input": "arr = [2, 1, 8, 7, 6, 5]", "output": "[2, 5, 1, 6, 7, 8]"}, "compiler": {"input": "6\\n2 1 8 7 6 5", "output": "2 5 1 6 7 8"}, "explanation": "The pivot is 1. The smallest number in the suffix [8, 7, 6, 5] greater than 1 is 5. We swap them to get [2, 5, 8, 7, 6, 1]. Then we reverse the new suffix [8, 7, 6, 1] to get [1, 6, 7, 8], resulting in the final answer."}]	\N	[{"input": "3\\n1 3 2", "output": "2 1 3"}, {"input": "3\\n3 2 1", "output": "1 2 3"}, {"input": "6\\n2 1 8 7 6 5", "output": "2 5 1 6 7 8"}, {"input": "1\\n9", "output": "9"}, {"input": "5\\n1 1 5 1 1", "output": "1 5 1 1 1"}, {"input": "4\\n4 4 4 4", "output": "4 4 4 4"}]	{"JAVA": {"template": "import java.util.*;\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            int n = scanner.nextInt();\\n            int[] arr = new int[n];\\n            for (int i = 0; i < n; i++) {\\n                arr[i] = scanner.nextInt();\\n            }\\n\\n            Solution sol = new Solution();\\n            sol.nextPermutation(arr);\\n\\n            for (int i = 0; i < n; i++) {\\n                System.out.print(arr[i] + (i == n - 1 ? \\"\\" : \\" \\"));\\n            }\\n            System.out.println();\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    public void nextPermutation(int[] arr) {\\n        // Write your code here\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = sys.stdin.readlines()\\n        n = int(lines[0].strip())\\n        arr = list(map(int, lines[1].strip().split()))\\n        \\n        sol = Solution()\\n        result = sol.nextPermutation(arr)\\n\\n        if result:\\n            print(' '.join(map(str, result)))\\n\\n    except (IOError, ValueError):\\n        pass", "userCode": "    def nextPermutation(self, arr: list[int]) -> list[int]:\\n        # Write your code here\\n        # The function should modify the array in-place and can return it.\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const n = parseInt(lines[0], 10);\\n        const arr = lines[1].split(' ').map(Number);\\n\\n        nextPermutation(arr);\\n\\n        console.log(arr.join(' '));\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {number[]} arr\\n * @return {void} Do not return anything, modify arr in-place instead.\\n */\\nvar nextPermutation = function(arr) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\npublic class Main {\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        int[] arr = new int[n];\\n        for (int i = 0; i < n; i++) {\\n            arr[i] = scanner.nextInt();\\n        }\\n\\n        // --- Logic for Next Permutation --- \\n        int i = n - 2;\\n        while (i >= 0 && arr[i] >= arr[i + 1]) {\\n            i--;\\n        }\\n\\n        if (i >= 0) {\\n            int j = n - 1;\\n            while (arr[j] <= arr[i]) {\\n                j--;\\n            }\\n            // Swap\\n            int temp = arr[i];\\n            arr[i] = arr[j];\\n            arr[j] = temp;\\n        }\\n\\n        // Reverse the suffix\\n        int start = i + 1;\\n        int end = n - 1;\\n        while (start < end) {\\n            int temp = arr[start];\\n            arr[start] = arr[end];\\n            arr[end] = temp;\\n            start++;\\n            end--;\\n        }\\n        // --- End of Logic --- \\n\\n        for (int k = 0; k < n; k++) {\\n            System.out.print(arr[k] + (k == n - 1 ? \\"\\" : \\" \\"));\\n        }\\n        System.out.println();\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    arr = list(map(int, lines[1].strip().split()))\\n\\n    # --- Logic for Next Permutation ---\\n    pivot = -1\\n    for i in range(n - 2, -1, -1):\\n        if arr[i] < arr[i + 1]:\\n            pivot = i\\n            break\\n    \\n    if pivot == -1:\\n        arr.reverse()\\n    else:\\n        for i in range(n - 1, pivot, -1):\\n            if arr[i] > arr[pivot]:\\n                arr[i], arr[pivot] = arr[pivot], arr[i]\\n                break\\n        \\n        # Reverse the suffix\\n        left, right = pivot + 1, n - 1\\n        while left < right:\\n            arr[left], arr[right] = arr[right], arr[left]\\n            left += 1\\n            right -= 1\\n    # --- End of Logic ---\\n\\n    print(' '.join(map(str, arr)))\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const n = parseInt(lines[0], 10);\\n    const arr = lines[1].split(' ').map(Number);\\n\\n    // --- Logic for Next Permutation ---\\n    let i = n - 2;\\n    while (i >= 0 && arr[i] >= arr[i + 1]) {\\n        i--;\\n    }\\n\\n    if (i >= 0) {\\n        let j = n - 1;\\n        while (arr[j] <= arr[i]) {\\n            j--;\\n        }\\n        [arr[i], arr[j]] = [arr[j], arr[i]]; // Swap\\n    }\\n\\n    let start = i + 1;\\n    let end = n - 1;\\n    while (start < end) {\\n        [arr[start], arr[end]] = [arr[end], arr[start]];\\n        start++;\\n        end--;\\n    }\\n    // --- End of Logic ---\\n\\n    console.log(arr.join(' '));\\n});"}	2025-07-31 19:25:53.133	2025-07-31 19:25:53.133	["1 <= arr.length <= 1000", "0 <= arr[i] <= 100000"]	{Amazon,Microsoft,Google,Bloomberg,"Goldman Sachs"}	\N
3febe6a7-aef9-41cb-a215-084fedc76f2e	Merge Overlapping Intervals	You are given a collection of intervals, where each interval is a pair of integers `[start, end]`. Your task is to merge all overlapping intervals and return an array of the non-overlapping intervals that cover all the intervals in the input. The final list of intervals should be sorted in ascending order by their start times.	MEDIUM	{Array,Sorting,Intervals,Greedy}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"display": {"input": "intervals = [[1,3],[2,6],[8,10],[15,18]]", "output": "[[1,6],[8,10],[15,18]]"}, "compiler": {"input": "4\\n1 3\\n2 6\\n8 10\\n15 18", "output": "3\\n1 6\\n8 10\\n15 18"}, "explanation": "The intervals [1,3] and [2,6] overlap, so they are merged into [1,6]. The other intervals do not overlap with any others."}, {"display": {"input": "intervals = [[1,4],[4,5]]", "output": "[[1,5]]"}, "compiler": {"input": "2\\n1 4\\n4 5", "output": "1\\n1 5"}, "explanation": "The intervals [1,4] and [4,5] are considered overlapping because they touch at the boundary, and they merge to form [1,5]."}]	\N	[{"input": "4\\n1 3\\n2 6\\n8 10\\n15 18", "output": "3\\n1 6\\n8 10\\n15 18"}, {"input": "2\\n1 4\\n4 5", "output": "1\\n1 5"}, {"input": "2\\n1 4\\n2 3", "output": "1\\n1 4"}, {"input": "4\\n6 8\\n1 9\\n2 4\\n4 7", "output": "1\\n1 9"}, {"input": "3\\n1 1\\n2 2\\n3 3", "output": "3\\n1 1\\n2 2\\n3 3"}]	{"JAVA": {"template": "import java.util.*;\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            int n = scanner.nextInt();\\n            int[][] intervals = new int[n][2];\\n            for (int i = 0; i < n; i++) {\\n                intervals[i][0] = scanner.nextInt();\\n                intervals[i][1] = scanner.nextInt();\\n            }\\n\\n            Solution sol = new Solution();\\n            int[][] result = sol.merge(intervals);\\n\\n            System.out.println(result.length);\\n            for (int[] interval : result) {\\n                System.out.println(interval[0] + \\" \\" + interval[1]);\\n            }\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    public int[][] merge(int[][] intervals) {\\n        // Write your code here\\n        return new int[0][0];\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = sys.stdin.readlines()\\n        n = int(lines[0].strip())\\n        intervals = []\\n        for i in range(1, n + 1):\\n            row = list(map(int, lines[i].strip().split()))\\n            intervals.append(row)\\n        \\n        sol = Solution()\\n        result = sol.merge(intervals)\\n\\n        if result is not None:\\n            print(len(result))\\n            for row in result:\\n                print(' '.join(map(str, row)))\\n\\n    except (IOError, ValueError):\\n        pass", "userCode": "    def merge(self, intervals: list[list[int]]) -> list[list[int]]:\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const n = parseInt(lines[0], 10);\\n        const intervals = [];\\n        for (let i = 1; i <= n; i++) {\\n            intervals.push(lines[i].split(' ').map(Number));\\n        }\\n\\n        const result = merge(intervals);\\n\\n        if (result) {\\n            console.log(result.length);\\n            result.forEach(row => console.log(row.join(' ')));\\n        }\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {number[][]} intervals\\n * @return {number[][]}\\n */\\nvar merge = function(intervals) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\npublic class Main {\\n    public static int[][] merge(int[][] intervals) {\\n        if (intervals.length <= 1) {\\n            return intervals;\\n        }\\n\\n        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));\\n\\n        List<int[]> merged = new ArrayList<>();\\n        int[] currentInterval = intervals[0];\\n        merged.add(currentInterval);\\n\\n        for (int[] interval : intervals) {\\n            int currentEnd = currentInterval[1];\\n            int nextBegin = interval[0];\\n            int nextEnd = interval[1];\\n\\n            if (currentEnd >= nextBegin) {\\n                currentInterval[1] = Math.max(currentEnd, nextEnd);\\n            } else {\\n                currentInterval = interval;\\n                merged.add(currentInterval);\\n            }\\n        }\\n\\n        return merged.toArray(new int[merged.size()][]);\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        int[][] intervals = new int[n][2];\\n        for (int i = 0; i < n; i++) {\\n            intervals[i][0] = scanner.nextInt();\\n            intervals[i][1] = scanner.nextInt();\\n        }\\n\\n        int[][] result = merge(intervals);\\n\\n        System.out.println(result.length);\\n        for (int[] interval : result) {\\n            System.out.println(interval[0] + \\" \\" + interval[1]);\\n        }\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\ndef merge(intervals):\\n    if not intervals:\\n        return []\\n\\n    intervals.sort(key=lambda x: x[0])\\n\\n    merged = []\\n    for interval in intervals:\\n        if not merged or merged[-1][1] < interval[0]:\\n            merged.append(interval)\\n        else:\\n            merged[-1][1] = max(merged[-1][1], interval[1])\\n\\n    return merged\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    intervals = []\\n    for i in range(1, n + 1):\\n        intervals.append(list(map(int, lines[i].strip().split())))\\n    \\n    result = merge(intervals)\\n    \\n    print(len(result))\\n    for row in result:\\n        print(' '.join(map(str, row)))\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction merge(intervals) {\\n    if (intervals.length === 0) {\\n        return [];\\n    }\\n\\n    intervals.sort((a, b) => a[0] - b[0]);\\n\\n    const merged = [intervals[0]];\\n\\n    for (let i = 1; i < intervals.length; i++) {\\n        const last = merged[merged.length - 1];\\n        const current = intervals[i];\\n\\n        if (last[1] >= current[0]) {\\n            last[1] = Math.max(last[1], current[1]);\\n        } else {\\n            merged.push(current);\\n        }\\n    }\\n\\n    return merged;\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const n = parseInt(lines[0], 10);\\n    const intervals = [];\\n    for (let i = 1; i <= n; i++) {\\n        intervals.push(lines[i].split(' ').map(Number));\\n    }\\n\\n    const result = merge(intervals);\\n\\n    console.log(result.length);\\n    result.forEach(row => console.log(row.join(' ')));\\n});"}	2025-07-31 19:32:19.228	2025-07-31 19:32:19.228	["1 <= intervals.length <= 10000", "0 <= start <= end <= 10^9"]	{Amazon,Google,Facebook,Microsoft,LinkedIn,Twitter}	\N
