on {\\n    public int[] searchRange(int[] nums, int key) {\\n        // Write your code here\\n        return new int[]{-1, -1};\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = sys.stdin.readlines()\\n        n, key = map(int, lines[0].strip().split())\\n        if n > 0:\\n            nums = list(map(int, lines[1].strip().split()))\\n        else:\\n            nums = []\\n        \\n        sol = Solution()\\n        result = sol.searchRange(nums, key)\\n        print(' '.join(map(str, result)))\\n\\n    except (IOError, ValueError):\\n        print('-1 -1')\\n        pass", "userCode": "    def searchRange(self, nums: list[int], key: int) -> list[int]:\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const [n, key] = lines[0].split(' ').map(Number);\\n        let nums = [];\\n        if (n > 0) {\\n            nums = lines[1].split(' ').map(Number);\\n        }\\n\\n        const result = searchRange(nums, key);\\n        console.log(result.join(' '));\\n    } catch (e) {\\n        console.log('-1 -1');\\n    }\\n});", "userCode": "/**\\n * @param {number[]} nums\\n * @param {number} key\\n * @return {number[]}\\n */\\nvar searchRange = function(nums, key) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\npublic class Main {\\n\\n    public static int[] searchRange(int[] nums, int key) {\\n        int first = findBound(nums, key, true);\\n        if (first == -1) {\\n            return new int[]{-1, -1};\\n        }\\n        int last = findBound(nums, key, false);\\n        return new int[]{first, last};\\n    }\\n\\n    private static int findBound(int[] nums, int key, boolean isFirst) {\\n        int low = 0, high = nums.length - 1;\\n        int result = -1;\\n\\n        while (low <= high) {\\n            int mid = low + (high - low) / 2;\\n            if (nums[mid] == key) {\\n                result = mid;\\n                if (isFirst) {\\n                    high = mid - 1; // Look for earlier occurrences\\n                } else {\\n                    low = mid + 1; // Look for later occurrences\\n                }\\n            } else if (nums[mid] < key) {\\n                low = mid + 1;\\n            } else {\\n                high = mid - 1;\\n            }\\n        }\\n        return result;\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        int key = scanner.nextInt();\\n        int[] nums = new int[n];\\n        if (n > 0) {\\n            for (int i = 0; i < n; i++) {\\n                nums[i] = scanner.nextInt();\\n            }\\n        }\\n\\n        int[] result = searchRange(nums, key);\\n        System.out.println(result[0] + \\" \\" + result[1]);\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\ndef find_bound(nums, key, is_first):\\n    low, high = 0, len(nums) - 1\\n    result = -1\\n    while low <= high:\\n        mid = (low + high) // 2\\n        if nums[mid] == key:\\n            result = mid\\n            if is_first:\\n                high = mid - 1\\n            else:\\n                low = mid + 1\\n        elif nums[mid] < key:\\n            low = mid + 1\\n        else:\\n            high = mid - 1\\n    return result\\n\\ndef search_range(nums, key):\\n    first = find_bound(nums, key, True)\\n    if first == -1:\\n        return [-1, -1]\\n    last = find_bound(nums, key, False)\\n    return [first, last]\\n\\ndef solve():\\n    try:\\n        lines = sys.stdin.readlines()\\n        n, key = map(int, lines[0].strip().split())\\n        if n > 0:\\n            nums = list(map(int, lines[1].strip().split()))\\n        else:\\n            nums = []\\n        \\n        result = search_range(nums, key)\\n        print(' '.join(map(str, result)))\\n    except (IOError, ValueError):\\n        print('-1 -1')\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction findBound(nums, key, isFirst) {\\n    let low = 0;\\n    let high = nums.length - 1;\\n    let result = -1;\\n\\n    while (low <= high) {\\n        const mid = Math.floor(low + (high - low) / 2);\\n        if (nums[mid] === key) {\\n            result = mid;\\n            if (isFirst) {\\n                high = mid - 1;\\n            } else {\\n                low = mid + 1;\\n            }\\n        } else if (nums[mid] < key) {\\n            low = mid + 1;\\n        } else {\\n            high = mid - 1;\\n        }\\n    }\\n    return result;\\n}\\n\\nfunction searchRange(nums, key) {\\n    const first = findBound(nums, key, true);\\n    if (first === -1) {\\n        return [-1, -1];\\n    }\\n    const last = findBound(nums, key, false);\\n    return [first, last];\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const [n, key] = lines[0].split(' ').map(Number);\\n        let nums = [];\\n        if (n > 0 && lines.length > 1) {\\n            nums = lines[1].split(' ').map(Number);\\n        }\\n\\n        const result = searchRange(nums, key);\\n        console.log(result.join(' '));\\n    } catch (e) {\\n        console.log('-1 -1');\\n    }\\n});"}	2025-07-31 19:34:30.774	2025-07-31 19:34:30.774	["0 <= nums.length <= 10000", "-10^6 <= nums[i], key <= 10^6"]	{Amazon,Facebook,Google,Microsoft,Adobe}	\N
