rn 0;\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = sys.stdin.readlines()\\n        n = int(lines[0].strip())\\n        nums = list(map(int, lines[1].strip().split()))\\n        k = int(lines[2].strip())\\n        \\n        sol = Solution()\\n        result = sol.findKthLargest(nums, k)\\n        print(result)\\n\\n    except (IOError, ValueError):\\n        pass", "userCode": "    def findKthLargest(self, nums: list[int], k: int) -> int:\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const n = parseInt(lines[0], 10);\\n        const nums = lines[1].split(' ').map(Number);\\n        const k = parseInt(lines[2], 10);\\n\\n        const result = findKthLargest(nums, k);\\n        console.log(result);\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {number[]} nums\\n * @param {number} k\\n * @return {number}\\n */\\nvar findKthLargest = function(nums, k) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\npublic class Main {\\n    public static int findKthLargest(int[] nums, int k) {\\n        return quickSelect(nums, 0, nums.length - 1, nums.length - k);\\n    }\\n\\n    private static int quickSelect(int[] nums, int left, int right, int k_smallest) {\\n        if (left == right) {\\n            return nums[left];\\n        }\\n\\n        int pivot_index = new Random().nextInt(right - left + 1) + left;\\n        pivot_index = partition(nums, left, right, pivot_index);\\n\\n        if (k_smallest == pivot_index) {\\n            return nums[k_smallest];\\n        } else if (k_smallest < pivot_index) {\\n            return quickSelect(nums, left, pivot_index - 1, k_smallest);\\n        } else {\\n            return quickSelect(nums, pivot_index + 1, right, k_smallest);\\n        }\\n    }\\n\\n    private static int partition(int[] nums, int left, int right, int pivot_index) {\\n        int pivot = nums[pivot_index];\\n        swap(nums, pivot_index, right);\\n        int store_index = left;\\n\\n        for (int i = left; i < right; i++) {\\n            if (nums[i] < pivot) {\\n                swap(nums, store_index, i);\\n                store_index++;\\n            }\\n        }\\n        swap(nums, right, store_index);\\n        return store_index;\\n    }\\n\\n    private static void swap(int[] nums, int a, int b) {\\n        int temp = nums[a];\\n        nums[a] = nums[b];\\n        nums[b] = temp;\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        int[] nums = new int[n];\\n        for (int i = 0; i < n; i++) {\\n            nums[i] = scanner.nextInt();\\n        }\\n        int k = scanner.nextInt();\\n        System.out.println(findKthLargest(nums, k));\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\nimport random\\n\\ndef find_kth_largest(nums, k):\\n    def quick_select(left, right, k_smallest):\\n        if left == right:\\n            return nums[left]\\n\\n        pivot_index = random.randint(left, right)\\n        pivot_index = partition(left, right, pivot_index)\\n\\n        if k_smallest == pivot_index:\\n            return nums[k_smallest]\\n        elif k_smallest < pivot_index:\\n            return quick_select(left, pivot_index - 1, k_smallest)\\n        else:\\n            return quick_select(pivot_index + 1, right, k_smallest)\\n\\n    def partition(left, right, pivot_index):\\n        pivot = nums[pivot_index]\\n        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]\\n        store_index = left\\n\\n        for i in range(left, right):\\n            if nums[i] < pivot:\\n                nums[store_index], nums[i] = nums[i], nums[store_index]\\n                store_index += 1\\n        \\n        nums[right], nums[store_index] = nums[store_index], nums[right]\\n        return store_index\\n\\n    return quick_select(0, len(nums) - 1, len(nums) - k)\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    nums = list(map(int, lines[1].strip().split()))\\n    k = int(lines[2].strip())\\n    \\n    result = find_kth_largest(nums, k)\\n    print(result)\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction findKthLargest(nums, k) {\\n    const quickSelect = (left, right, kSmallest) => {\\n        if (left === right) {\\n            return nums[left];\\n        }\\n\\n        let pivotIndex = Math.floor(Math.random() * (right - left + 1)) + left;\\n        pivotIndex = partition(left, right, pivotIndex);\\n\\n        if (kSmallest === pivotIndex) {\\n            return nums[kSmallest];\\n        } else if (kSmallest < pivotIndex) {\\n            return quickSelect(left, pivotIndex - 1, kSmallest);\\n        } else {\\n            return quickSelect(pivotIndex + 1, right, kSmallest);\\n        }\\n    };\\n\\n    const partition = (left, right, pivotIndex) => {\\n        const pivot = nums[pivotIndex];\\n        [nums[pivotIndex], nums[right]] = [nums[right], nums[pivotIndex]]; // Move pivot to end\\n        let storeIndex = left;\\n\\n        for (let i = left; i < right; i++) {\\n            if (nums[i] < pivot) {\\n                [nums[storeIndex], nums[i]] = [nums[i], nums[storeIndex]];\\n                storeIndex++;\\n            }\\n        }\\n        [nums[right], nums[storeIndex]] = [nums[storeIndex], nums[right]]; // Move pivot to its final place\\n        return storeIndex;\\n    };\\n\\n    return quickSelect(0, nums.length - 1, nums.length - k);\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const n = parseInt(lines[0], 10);\\n    const nums = lines[1].split(' ').map(Number);\\n    const k = parseInt(lines[2], 10);\\n\\n    const result = findKthLargest(nums, k);\\n    console.log(result);\\n});"}	2025-07-31 19:35:24.136	2025-07-31 19:35:24.136	["1 <= k <= nums.length <= 10000", "-10^5 <= nums[i] <= 10^5"]	{Amazon,Facebook,Microsoft,Apple,Google}	\N
1443a2ec-e45d-4e8f-8348-6b4f2e999f3c	Square Root of an Integer	Given a non-negative integer `n`, your task is to compute and return the integer part of its square root. Since the return type is an integer, the decimal digits are truncated, and only the integer part of the result is returned.\n\n**Note:** You are not allowed to use any built-in exponent function or operator (like `pow(x, 0.5)` or `x ** 0.5`). The expected time complexity is $O(\\log n)$	EASY	{"Binary Search",Math,Algorithm}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"display": {"input": "n = 8", "output": "2"}, "compiler": {"input": "8", "output": "2"}, "explanation": "The square root of 8 is approximately 2.828. The integer part is 2."}, {"display": {"input": "n = 4", "output": "2"}, "compiler": {"input": "4", "output": "2"}, "explanation": "The square root of 4 is exactly 2."}]	\N	[{"input": "8", "output": "2"}, {"input": "4", "output": "2"}, {"input": "2147395599", "output": "46339"}, {"input": "0", "output": "0"}, {"input": "1", "output": "1"}]	{"JAVA": {"template": "import java.util.*;\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            int n = scanner.nextInt();\\n            Solution sol = new Solution();\\n            int result = sol.mySqrt(n);\\n            System.out.println(result);\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    public int mySqrt(int n) {\\n        // Write your code here\\n        return 0;\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        n = int(sys.stdin.readline().strip())\\n        sol = Solution()\\n        result = sol.mySqrt(n)\\n        print(result)\\n\\n    except (IOError, ValueError):\\n        pass", "userCode": "    def mySqrt(self, n: int) -> int:\\n        # Write your code her