('readline');\\n\\nfunction mySqrt(n) {\\n    if (n === 0) return 0;\\n    \\n    let low = 1, high = n;\\n    let ans = 0;\\n\\n    while (low <= high) {\\n        const mid = Math.floor(low + (high - low) / 2);\\n        const midSq = mid * mid;\\n\\n        if (midSq === n) {\\n            return mid;\\n        } else if (midSq < n) {\\n            ans = mid;\\n            low = mid + 1;\\n        } else {\\n            high = mid - 1;\\n        }\\n    }\\n    return ans;\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nrl.on('line', (line) => {\\n    const n = parseInt(line.trim(), 10);\\n    const result = mySqrt(n);\\n    console.log(result);\\n    rl.close();\\n});"}	2025-07-31 19:35:47.257	2025-07-31 19:35:47.257	["0 <= n <= 2^31 - 1"]	{Amazon,Facebook,Microsoft,Apple,Bloomberg}	\N
