 // Check if the left half is sorted\\n            if (nums[low] <= nums[mid]) {\\n                if (target >= nums[low] && target < nums[mid]) {\\n                    high = mid - 1;\\n                } else {\\n                    low = mid + 1;\\n                }\\n            } \\n            // Otherwise, the right half is sorted\\n            else {\\n                if (target > nums[mid] && target <= nums[high]) {\\n                    low = mid + 1;\\n                } else {\\n                    high = mid - 1;\\n                }\\n            }\\n        }\\n        return -1;\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        int[] nums = new int[n];\\n        for (int i = 0; i < n; i++) {\\n            nums[i] = scanner.nextInt();\\n        }\\n        int target = scanner.nextInt();\\n        System.out.println(search(nums, target));\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\ndef search(nums, target):\\n    low, high = 0, len(nums) - 1\\n    \\n    while low <= high:\\n        mid = (low + high) // 2\\n        \\n        if nums[mid] == target:\\n            return mid\\n        \\n        # Left half is sorted\\n        if nums[low] <= nums[mid]:\\n            if nums[low] <= target < nums[mid]:\\n                high = mid - 1\\n            else:\\n                low = mid + 1\\n        # Right half is sorted\\n        else:\\n            if nums[mid] < target <= nums[high]:\\n                low = mid + 1\\n            else:\\n                high = mid - 1\\n                \\n    return -1\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    nums = list(map(int, lines[1].strip().split()))\\n    target = int(lines[2].strip())\\n    \\n    result = search(nums, target)\\n    print(result)\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction search(nums, target) {\\n    let low = 0;\\n    let high = nums.length - 1;\\n\\n    while (low <= high) {\\n        const mid = Math.floor(low + (high - low) / 2);\\n\\n        if (nums[mid] === target) {\\n            return mid;\\n        }\\n\\n        // Check if the left half is sorted\\n        if (nums[low] <= nums[mid]) {\\n            if (target >= nums[low] && target < nums[mid]) {\\n                high = mid - 1;\\n            } else {\\n                low = mid + 1;\\n            }\\n        } \\n        // Otherwise, the right half is sorted\\n        else {\\n            if (target > nums[mid] && target <= nums[high]) {\\n                low = mid + 1;\\n            } else {\\n                high = mid - 1;\\n            }\\n        }\\n    }\\n    return -1;\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const n = parseInt(lines[0], 10);\\n    const nums = lines[1].split(' ').map(Number);\\n    const target = parseInt(lines[2], 10);\\n    const result = search(nums, target);\\n    console.log(result);\\n});"}	2025-07-31 19:37:04.851	2025-07-31 19:37:04.851	["1 <= nums.length <= 10000", "All values of nums are unique.", "-10^6 <= nums[i], target <= 10^6"]	{Adobe,Amazon,Facebook,Flipkart,Google,MakeMyTrip,Microsoft,Paytm,Snapdeal}	\N
6141ad13-e331-43b1-91e1-718a57b92455	Sort Colors (Dutch National Flag Problem)	Given an array `nums` with n objects colored red, white, or blue, sort them **in-place** so that objects of the same color are adjacent, with the order red, white, and blue. We will use the integers 0, 1, and 2 to represent the color red, white, and blue, respectively.\n\nYou must solve this problem without using the library's sort function and ideally in a single pass with constant extra space.	MEDIUM	{Array,"Two Pointers",Sorting,In-Place}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"display": {"input": "nums = [2, 0, 2, 1, 1, 0]", "output": "[0, 0, 1, 1, 2, 2]"}, "compiler": {"input": "6\\n2 0 2 1 1 0", "output": "0 0 1 1 2 2"}, "explanation": "All 0s are moved to the beginning, 1s to the middle, and 2s to the end."}, {"display": {"input": "nums = [2, 0, 1]", "output": "[0, 1, 2]"}, "compiler": {"input": "3\\n2 0 1", "output": "0 1 2"}, "explanation": "The array is sorted according to the color codes 0, 1, and 2."}]	\N	[{"input": "6\\n2 0 2 1 1 0", "output": "0 0 1 1 2 2"}, {"input": "3\\n2 0 1", "output": "0 1 2"}, {"input": "3\\n0 0 0", "output": "0 0 0"}, {"input": "4\\n2 1 2 0", "output": "0 1 2 2"}, {"input": "1\\n1", "output": "1"}]	{"JAVA": {"template": "import java.util.*;\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            int n = scanner.nextInt();\\n            int[] nums = new int[n];\\n            for (int i = 0; i < n; i++) {\\n                nums[i] = scanner.nextInt();\\n            }\\n\\n            Solution sol = new Solution();\\n            sol.sortColors(nums);\\n\\n            for (int i = 0; i < n; i++) {\\n                System.out.print(nums[i] + (i == n - 1 ? \\"\\" : \\" \\"));\\n            }\\n            System.out.println();\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    public void sortColors(int[] nums) {\\n        // Write your code here\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = sys.stdin.readlines()\\n        n = int(lines[0].strip())\\n        nums = list(map(int, lines[1].strip().split()))\\n        \\n        sol = Solution()\\n        sol.sortColors(nums)\\n\\n        print(' '.join(map(str, nums)))\\n\\n    except (IOError, ValueError):\\n        pass", "userCode": "    def sortColors(self, nums: list[int]) -> None:\\n        \\"\\"\\"\\n        Do not return anything, modify nums in-place instead.\\n        \\"\\"\\"\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const n = parseInt(lines[0], 10);\\n        const nums = lines[1].split(' ').map(Number);\\n\\n        sortColors(nums);\\n\\n        console.log(nums.join(' '));\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {number[]} nums\\n * @return {void} Do not return anything, modify nums in-place instead.\\n */\\nvar sortColors = function(nums) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\npublic class Main {\\n    public static void sortColors(int[] nums) {\\n        int low = 0;\\n        int mid = 0;\\n        int high = nums.length - 1;\\n        int temp;\\n\\n        while (mid <= high) {\\n            switch (nums[mid]) {\\n                case 0: {\\n                    temp = nums[low];\\n                    nums[low] = nums[mid];\\n                    nums[mid] = temp;\\n                    low++;\\n                    mid++;\\n                    break;\\n                }\\n                case 1: {\\n                    mid++;\\n                    break;\\n                }\\n                case 2: {\\n                    temp = nums[mid];\\n                    nums[mid] = nums[high];\\n                    nums[high] = temp;\\n                    high--;\\n                    break;\\n                }\\n            }\\n        }\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        int[] nums = new int[n];\\n        for (int i = 0; i < n; i++) {\\n            nums[i] = scanner.nextInt();\\n        }\\n        sortColors(nums);\\n        for (int i = 0; i < n; i++) {\\n            System.out.print(nums[i] + (i == n - 1 ? \\"\\" : \\" \\"));\\n        }\\n        System.out.println();\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\ndef sort_colors(nums):\\n    low, mid, high = 0, 0, len(nums) - 1\\n    \\n    while mid <= high:\\n        if nums[mid] == 0:\\n            nums[low], nums[mid] = nums[mid], nums[low]\\n            low += 1\\n            mid += 1\\n        elif nums[mid] == 1:\\n            mid += 1\\n        else: # nums[mid] == 2\\n            nums[mid], nums[high] = nums[high], nums[mid]\\n            high -= 1\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    nums = list(map(int, lines[1].strip().split()))\\n    \\n    sort_colors(nums)\\n    \\n    print(' '.join(map(str, nums)))\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction sortColors(nums) {\\n    let low = 0;\\n    let mid = 0;\\n    let high = nums.length - 1;\\n\\n    while (mid <= high) {\\n        if (nums[mid] === 0) {\\n            [nums[low], nums[mid]] = [nums[mid], nums[low]];\\n            low++;\\n            mid++;\\n        } else if (nums[mid] === 1) {\\n            mid++;\\n        } else { // nums[mid] === 2\\n            [nums[mid], nums[high]] = [nums[high], nums[mid]];\\n            high--;\\n        }\\n    }\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const n = parseInt(lines[0], 10);\\n    const nums = lines[1].split(' ').map(Number);\\n    sortColors(nums);\\n    console.log(nums.join(' '));\\n});"}	2025-07-31 19:37:37.507	2025-07-31 19:37:37.507	["1 <= nums.length <= 100000", "nums[i] is either 0, 1, or 2."]	{Amazon,MakeMyTrip,Microsoft,Facebook,Google}	\N
