        sol = Solution()\\n        result = sol.trap(height)\\n        print(result)\\n\\n    except (IOError, ValueError):\\n        pass", "userCode": "    def trap(self, height: list[int]) -> int:\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const n = parseInt(lines[0], 10);\\n        const height = lines[1].split(' ').map(Number);\\n\\n        const result = trap(height);\\n        console.log(result);\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {number[]} height\\n * @return {number}\\n */\\nvar trap = function(height) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\npublic class Main {\\n    public static int trap(int[] height) {\\n        if (height == null || height.length == 0) {\\n            return 0;\\n        }\\n        int left = 0, right = height.length - 1;\\n        int leftMax = 0, rightMax = 0;\\n        int water = 0;\\n\\n        while (left < right) {\\n            if (height[left] < height[right]) {\\n                if (height[left] >= leftMax) {\\n                    leftMax = height[left];\\n                } else {\\n                    water += leftMax - height[left];\\n                }\\n                left++;\\n            } else {\\n                if (height[right] >= rightMax) {\\n                    rightMax = height[right];\\n                } else {\\n                    water += rightMax - height[right];\\n                }\\n                right--;\\n            }\\n        }\\n        return water;\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        int[] height = new int[n];\\n        for (int i = 0; i < n; i++) {\\n            height[i] = scanner.nextInt();\\n        }\\n        System.out.println(trap(height));\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\ndef trap(height):\\n    if not height:\\n        return 0\\n    \\n    left, right = 0, len(height) - 1\\n    left_max, right_max = 0, 0\\n    water = 0\\n    \\n    while left < right:\\n        if height[left] < height[right]:\\n            if height[left] >= left_max:\\n                left_max = height[left]\\n            else:\\n                water += left_max - height[left]\\n            left += 1\\n        else:\\n            if height[right] >= right_max:\\n                right_max = height[right]\\n            else:\\n                water += right_max - height[right]\\n            right -= 1\\n            \\n    return water\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    height = list(map(int, lines[1].strip().split()))\\n    \\n    result = trap(height)\\n    print(result)\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction trap(height) {\\n    if (!height || height.length === 0) {\\n        return 0;\\n    }\\n\\n    let left = 0;\\n    let right = height.length - 1;\\n    let leftMax = 0;\\n    let rightMax = 0;\\n    let water = 0;\\n\\n    while (left < right) {\\n        if (height[left] < height[right]) {\\n            if (height[left] >= leftMax) {\\n                leftMax = height[left];\\n            } else {\\n                water += leftMax - height[left];\\n            }\\n            left++;\\n        } else {\\n            if (height[right] >= rightMax) {\\n                rightMax = height[right];\\n            } else {\\n                water += rightMax - height[right];\\n            }\\n            right--;\\n        }\\n    }\\n    return water;\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const n = parseInt(lines[0], 10);\\n    const height = lines[1].split(' ').map(Number);\\n    const result = trap(height);\\n    console.log(result);\\n});"}	2025-07-31 19:38:10.103	2025-07-31 19:38:10.103	["1 <= n <= 30000", "0 <= height[i] <= 10000"]	{Amazon,"Goldman Sachs",Microsoft,Qualcomm,Google,Facebook,Apple}	\N
84782f3e-fdbd-4cbe-a671-facdae1c10ef	K-diff Pairs in an Array	Given an array of integers `nums` and an integer `k`, return the number of **unique** k-diff pairs in the array.\n\nA k-diff pair is an integer pair `(nums[i], nums[j])`, where the following are true:\n\n- `0 <= i, j < nums.length`\n- `i != j`\n- `|nums[i] - nums[j]| == k`\n\nNote that `(nums[i], nums[j])` and `(nums[j], nums[i])` are considered the same pair.	MEDIUM	{Array,"Two Pointers","Hash Table","Binary Search",Sorting}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"display": {"input": "nums = [3, 1, 4, 1, 5], k = 2", "output": "2"}, "compiler": {"input": "5 2\\n3 1 4 1 5", "output": "2"}, "explanation": "There are two 2-diff pairs in the array: (1, 3) and (3, 5). Although there are two 1s in the input, we should only return the number of unique pairs."}, {"display": {"input": "nums = [1, 2, 3, 4, 5], k = 1", "output": "4"}, "compiler": {"input": "5 1\\n1 2 3 4 5", "output": "4"}, "explanation": "There are four 1-diff pairs in the array: (1, 2), (2, 3), (3, 4) and (4, 5)."}, {"display": {"input": "nums = [1, 3, 1, 5, 4], k = 0", "output": "1"}, "compiler": {"input": "5 0\\n1 3 1 5 4", "output": "1"}, "explanation": "There is one 0-diff pair in the array: (1, 1)."}]	\N	[{"input": "5 2\\n3 1 4 1 5", "output": "2"}, {"input": "5 1\\n1 2 3 4 5", "output": "4"}, {"input": "5 0\\n1 3 1 5 4", "output": "1"}, {"input": "5 0\\n1 1 1 1 1", "output": "1"}, {"input": "2 0\\n1 1", "output": "1"}]	{"JAVA": {"template": "import java.util.*;\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            int n = scanner.nextInt();\\n            int k = scanner.nextInt();\\n            int[] nums = new int[n];\\n            for (int i = 0; i < n; i++) {\\n                nums[i] = scanner.nextInt();\\n            }\\n\\n            Solution sol = new Solution();\\n            int result = sol.findPairs(nums, k);\\n            System.out.println(result);\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    public int findPairs(int[] nums, int k) {\\n        // Write your code here\\n        return 0;\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = sys.stdin.readlines()\\n        n, k = map(int, lines[0].strip().split())\\n        nums = list(map(int, lines[1].strip().split()))\\n        \\n        sol = Solution()\\n        result = sol.findPairs(nums, k)\\n        print(result)\\n\\n    except (IOError, ValueError):\\n        pass", "userCode": "    def findPairs(self, nums: list[int], k: int) -> int:\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const [n, k] = lines[0].split(' ').map(Number);\\n        const nums = lines[1].split(' ').map(Number);\\n\\n        const result = findPairs(nums, k);\\n        console.log(result);\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {number[]} nums\\n * @param {number} k\\n * @return {number}\\n */\\nvar findPairs = function(nums, k) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\npublic class Main {\\n    public static int findPairs(int[] nums, int k) {\\n        if (k < 0) {\\n            return 0;\\n        }\\n        if (k == 0) {\\n            Map<Integer, Integer> freqMap = new HashMap<>();\\n            for (int num : nums) {\\n                freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);\\n            }\\n            int count = 0;\\n            for (int freq : freqMap.values()) {\\n                if (freq > 1) {\\n                    count++;\\n                }\\n            }\\n            return count;\\n        } else {\\n            Set<Integer> set = new HashSet<>();\\n            for (int num : nums) {\\n                set.add(num);\\n            }\\n            int count = 0;\\n            for (int num : set) {\\n                if (set.contains(num + k)) {\\n                    count++;\\n                }\\n            }\\n            return count;\\n        }\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        int k = scanner.nextInt();\\n        int[] nums = new int[n];\\n        for (int i = 0; i < n; i++) {\\n            nums[i] = scanner.nextInt();\\n        }\\n        System.out.println(findPairs(nums, k));\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\nfrom collections import Counter\\n\\ndef find_pairs(nums, k):\\n    if k < 0:\\n        return 0\\n    \\n    if k == 0:\\n        freq = Counter(nums)\\n        return sum(1 for count in freq.values() if count > 1)\\n    else:\\n        num_set = set(nums)\\n        count = 0\\n        for num in num_set:\\n            if num + k in num_set:\\n                count += 1\\n        return count\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n, k = map(int, lines[0].strip().split())\\n    nums = list(map(int, lines[1].strip().split()))\\n    \\n    result = find_pairs(nums, k)\\n    print(result)\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction findPairs(nums, k) {\\n    if (k < 0) {\\n        return 0;\\n    }\\n\\n    if (k === 0) {\\n        const freq = new Map();\\n        for (const num of nums) {\\n            freq.set(num, (freq.get(num) || 0) + 1);\\n        }\\n        let count = 0;\\n        for (const val of freq.values()) {\\n            if (val > 1) {\\n                count++;\\n            }\\n        }\\n        return count;\\n    } else {\\n        const numSet = new Set(nums);\\n        let count = 0;\\n        for (const num of numSet) {\\n            if (numSet.has(num + k)) {\\n                count++;\\n            }\\n        }\\n        return count;\\n    }\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const [n, k] = lines[0].split(' ').map(Number);\\n    const nums = lines[1].split(' ').map(Number);\\n    const result = findPairs(nums, k);\\n    console.log(result);\\n});"}	2025-07-31 19:38:48.557	2025-07-31 19:38:48.557	["1 <= nums.length <= 10000", "-10^7 <= nums[i] <= 10^7", "0 <= k <= 10^7"]	{Amazon,Facebook,Microsoft,Google}	\N
033d5463-9749-48fa-8664-b90e9d69e527	Reverse Linked List	Given the `head` of a singly linked list, reverse the list, and return the new head of the reversed list. ≡ƒöä	EASY	{"Linked List",Recursion,"Two Pointers"}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"display": {"input": "head = [1, 2, 3, 4, 5]", "output": "[5, 4, 3, 2, 1]"}, "compiler": {"input": "5\\n1 2 3 4 5", "output": "5 4 3 2 1"}, "explanation": "The original list is reversed node by node."}, {"display": {"input": "head = [1, 2]", "output": "[2, 1]"}, "compiler": {"input": "2\\n1 2", "output": "2 1"}, "explanation": "A list with two nodes is reversed."}]	\N	[{"input": "5\\n1 2 3 4 5", "output": "5 4 3 2 1"}, {"input": "1\\n10", "output": "10"}, {"input": "0\\n", "output": ""}, {"input": "4\\n1 0 1 2", "output": "2 1 0 1"}]	{"JAVA": {"template": "import java.util.*;\\n\\nclass ListNode {\\n    int val;\\n    ListNode next;\\n    ListNode(int x) { val = x; next = null; }\\n}\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            int n = scanner.nextInt();\\n            ListNode head = null, tail = null;\\n            if (n > 0) {\\n                head = new ListNode(scanner.nextInt());\\n                tail = head;\\n                for (int i = 1; i < n; i++) {\\n                    tail.next = new ListNode(scanner.nextInt());\\n                    tail = tail.next;\\n                }\\n            }\\n            Solution sol = new Solution();\\n            ListNode resultHead = sol.reverseList(head);\\n            StringBuilder sb = new StringBuilder();\\n            while(resultHead != null) {\\n                sb.append(resultHead.val).append(\\" \\");\\n                resultHead = resultHead.next;\\n            }\\n            System.out.println(sb.toString().trim());\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    public ListNode reverseList(ListNode head) {\\n        // Write your code here\\n        return null;\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass ListNode:\\n    def __init__(self, x):\\n        self.val = x\\n        self.next = None\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = sys.stdin.readlines()\\n        n = int(lines[0].strip())\\n        head, tail = None, None\\n        if n > 0:\\n            nodes = list(map(int, lines[1].strip().split()))\\n            head = ListNode(nodes[0])\\n            tail = head\\n            for i in range(1, n):\\n                tail.next = ListNode(nodes[i])\\n                tail = tail.next\\n        \\n        sol = Solution()\\n        result_head = sol.reverseList(head)\\n        \\n        res = []\\n        curr = result_head\\n        while curr:\\n            res.append(str(curr.val))\\n            curr = curr.next\\n        print(' '.join(res))\\n\\n    except (IOError, ValueError, IndexError):\\n        pass", "userCode": "    def reverseList(self, head: ListNode) -> ListNode:\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\nfunction ListNode(val, next) {\\n    this.val = (val===undefined ? 0 : val)\\n    this.next = (next===undefined ? null : next)\\n}\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const n = parseInt(lines[0], 10);\\n        let head = null;\\n        if (n > 0) {\\n            const values = lines[1].split(' ').map(Number);\\n            let current = head = new ListNode(values[0]);\\n            for (let i = 1; i < n; i++) {\\n                current.next = new ListNode(values[i]);\\n                current = current.next;\\n            }\\n        }\\n        const resultHead = reverseList(head);\\n        const result = [];\\n        let current = resultHead;\\n        while(current) {\\n            result.push(current.val);\\n            current = current.next;\\n        }\\n        console.log(result.join(' '));\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {ListNode} head\\n * @return {ListNode}\\n */\\nvar reverseList = function(head) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\nclass ListNode {\\n    int val;\\n    ListNode next;\\n    ListNode(int x) { val = x; next = null; }\\n}\\n\\npublic class Main {\\n    public static ListNode reverseList(ListNode head) {\\n        ListNode prev = null;\\n        ListNode curr = head;\\n        while (curr != null) {\\n            ListNode nextTemp = curr.next;\\n            curr.next = prev;\\n            prev = curr;\\n            curr = nextTemp;\\n        }\\n        return prev;\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        ListNode head = null, tail = null;\\n        if (n > 0) {\\n            head = new ListNode(scanner.nextInt());\\n            tail = head;\\n            for (int i = 1; i < n; i++) {\\n                tail.next = new ListNode(scanner.nextInt());\\n                tail = tail.next;\\n            }\\n        }\\n        ListNode resultHead = reverseList(head);\\n        StringBuilder sb = new StringBuilder();\\n        while(resultHead != null) {\\n            sb.append(resultHead.val).append(\\" \\");\\n            resultHead = resultHead.next;\\n        }\\n        System.out.println(sb.toString().trim());\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\nclass ListNode:\\n    def __init__(self, x):\\n        self.val = x\\n        self.next = None\\n\\ndef reverse_list(head: ListNode) -> ListNode:\\n    prev = None\\n    curr = head\\n    