eadA = null, tailA = null;\\n        if (l1 > 0) {\\n            const aNodes = lines[1].split(' ').map(Number);\\n            headA = new ListNode(aNodes[0]);\\n            tailA = headA;\\n            for (let i = 1; i < l1; i++) {\\n                tailA.next = new ListNode(aNodes[i]);\\n                tailA = tailA.next;\\n            }\\n        }\\n\\n        let headB = null, tailB = null;\\n        if (l2 > 0) {\\n            const bNodes = lines[2].split(' ').map(Number);\\n            headB = new ListNode(bNodes[0]);\\n            tailB = headB;\\n            for (let i = 1; i < l2; i++) {\\n                tailB.next = new ListNode(bNodes[i]);\\n                tailB = tailB.next;\\n            }\\n        }\\n\\n        const l3 = parseInt(lines[3], 10);\\n        if (l3 > 0) {\\n            const cNodes = lines[4].split(' ').map(Number);\\n            const commonHead = new ListNode(cNodes[0]);\\n            let commonTail = commonHead;\\n            for (let i = 1; i < l3; i++) {\\n                commonTail.next = new ListNode(cNodes[i]);\\n                commonTail = commonTail.next;\\n            }\\n            if (tailA) { tailA.next = commonHead; } else { headA = commonHead; }\\n            if (tailB) { tailB.next = commonHead; } else { headB = commonHead; }\\n        }\\n\\n        const resultNode = getIntersectionNode(headA, headB);\\n        console.log(resultNode ? resultNode.val : -1);\\n    } catch (e) {\\n        console.log(-1);\\n    }\\n});", "userCode": "/**\\n * @param {ListNode} headA\\n * @param {ListNode} headB\\n * @return {ListNode}\\n */\\nvar getIntersectionNode = function(headA, headB) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\nclass ListNode {\\n    int val;\\n    ListNode next;\\n    ListNode(int x) { val = x; next = null; }\\n}\\n\\npublic class Main {\\n    public static ListNode getIntersectionNode(ListNode headA, ListNode headB) {\\n        if (headA == null || headB == null) return nul