1);\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "PYTHON": "import sys\\n\\nclass ListNode:\\n    def __init__(self, x):\\n        self.val = x\\n        self.next = None\\n\\ndef get_intersection_node(headA: ListNode, headB: ListNode) -> 'ListNode':\\n    if not headA or not headB:\\n        return None\\n    p1, p2 = headA, headB\\n    while p1 is not p2:\\n        p1 = headB if p1 is None else p1.next\\n        p2 = headA if p2 is None else p2.next\\n    return p1\\n\\ndef solve():\\n    try:\\n        lines = [line.strip() for line in sys.stdin.readlines() if line.strip()]\\n        l1, l2 = map(int, lines[0].split())\\n        line_idx = 1\\n        headA, tailA = None, None\\n        if l1 > 0:\\n            a_nodes = list(map(int, lines[line_idx].split()))\\n            line_idx += 1\\n            headA = ListNode(a_nodes[0])\\n            tailA = headA\\n            for i in range(1, l1):\\n                tailA.next = ListNode(a_nodes[i])\\n                tailA = tailA.next\\n\\n        headB, tailB = None, None\\n        if l2 > 0:\\n            b_nodes = list(map(int, lines[line_idx].split()))\\n            line_idx += 1\\n            headB = ListNode(b_nodes[0])\\n            tailB = headB\\n            for i in range(1, l2):\\n                tailB.next = ListNode(b_nodes[i])\\n                tailB = tailB.next\\n\\n        l3 = int(lines[line_idx])\\n        line_idx += 1\\n        if l3 > 0:\\n            c_nodes = list(map(int, lines[line_idx].split()))\\n            common_head = ListNode(c_nodes[0])\\n            common_tail = common_head\\n            for i in range(1, l3):\\n                common_tail.next = ListNode(c_nodes[i])\\n                common_tail = common_tail.next\\n            \\n            if tailA: tailA.next = common_head\\n            else: headA = common_head\\n            if tailB: tailB.next = common_head\\n            else: headB = common_head\\n\\n        result_node = get_intersection_node(headA, headB)\\n        print(result_node.val if result_node else -1)\\n\\n    except (IOError, ValueError, IndexError):\\n        print(-1)\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction ListNode(val) {\\n    this.val = val;\\n    this.next = null;\\n}\\n\\nfunction getIntersectionNode(headA, headB) {\\n    if (!headA || !headB) return null;\\n    let p1 = headA;\\n    let p2 = headB;\\n    while (p1 !== p2) {\\n        p1 = (p1 === null) ? headB : p1.next;\\n        p2 = (p2 === null) ? headA : p2.next;\\n    }\\n    return p1;\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line.trim());\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        lines = lines.filter(line => line);\\n        const [l1, l2] = lines[0].split(' ').map(Number);\\n        let lineIdx = 1;\\n        let headA = null, tailA = null;\\n        if (l1 > 0) {\\n            const aNodes = lines[lineIdx++].split(' ').map(Number);\\n            headA = new ListNode(aNodes[0]);\\n            tailA = headA;\\n            for (let i = 1; i < l1; i++) {\\n                tailA.next = new ListNode(aNodes[i]);\\n                tailA = tailA.next;\\n            }\\n        }\\n\\n        let headB = null, tailB = null;\\n        if (l2 > 0) {\\n            const bNodes = lines[lineIdx++].split(' ').map(Number);\\n            headB = new ListNode(bNodes[0]);\\n            tailB = headB;\\n            for (let i = 1; i < l2; i++) {\\n                tailB.next = new ListNode(bNodes[i]);\\n                tailB = tailB.next;\\n            }\\n        }\\n\\n        const l3 = parseInt(lines[lineIdx++], 10);\\n        if (l3 > 0) {\\n            const cNodes = lines[lineIdx++].split(' ').map(Number);\\n            const commonHead = new ListNode(cNodes[0]);\\n            let commonTail = commonHead;\\n            for (l