     \\n            Solution sol = new Solution();\\n            ListNode resultHead = sol.mergeTwoLists(list1, list2);\\n\\n            StringBuilder sb = new StringBuilder();\\n            while(resultHead != null) {\\n                sb.append(resultHead.val).append(\\" \\");\\n                resultHead = resultHead.next;\\n            }\\n            System.out.println(sb.toString().trim());\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {\\n        // Write your code here\\n        return null;\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass ListNode:\\n    def __init__(self, x):\\n        self.val = x\\n        self.next = None\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\ndef build_list(nodes_data):\\n    if not nodes_data:\\n        return None\\n    head = ListNode(nodes_data[0])\\n    tail = head\\n    for i in range(1, len(nodes_data)):\\n        tail.next = ListNode(nodes_data[i])\\n        tail = tail.next\\n    return head\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = [line.strip() for line in sys.stdin.readlines()]\\n        n, m = map(int, lines[0].split())\\n        \\n        list1_data = list(map(int, lines[1].split())) if n > 0 and len(lines) > 1 else []\\n        list2_data = list(map(int, lines[2].split())) if m > 0 and len(lines) > 2 else []\\n\\n        list1 = build_list(list1_data)\\n        list2 = build_list(list2_data)\\n\\n        sol = Solution()\\n        result_head = sol.mergeTwoLists(list1, list2)\\n        \\n        res = []\\n        curr = result_head\\n        while curr:\\n            res.append(str(curr.val))\\n            curr = curr.next\\n        print(' '.join(res))\\n\\n    except (IOError, ValueError, IndexError):\\n        pass", "userCode": "    def mergeTwoLists(self, list1: 'ListNode', list2: 'ListNode') -> 'ListNode':\\n        # Write your code here\\n    