de(values[i]);\\n        current = current.next;\\n    }\\n    return head;\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const [n, m] = lines[0].split(' ').map(Number);\\n        const list1_values = n > 0 && lines.length > 1 && lines[1] ? lines[1].split(' ').map(Number) : [];\\n        const list2_values = m > 0 && lines.length > 2 && lines[2] ? lines[2].split(' ').map(Number) : [];\\n\\n        const list1 = buildList(list1_values);\\n        const list2 = buildList(list2_values);\\n\\n        const resultHead = mergeTwoLists(list1, list2);\\n        const result = [];\\n        let current = resultHead;\\n        while(current) {\\n            result.push(current.val);\\n            current = current.next;\\n        }\\n        console.log(result.join(' '));\\n    } catch (e) {}\\n});"}	2025-07-31 19:55:59.084	2025-07-31 19:55:59.084	["The number of nodes in both lists is in the range [0, 1000].", "-10^6 <= Node.val <= 10^6"]	{Adobe,Amazon,Microsoft,Yahoo,Apple}	\N
