r sb = new StringBuilder();\\n        while(resultHead != null) {\\n            sb.append(resultHead.val).append(\\" \\");\\n            resultHead = resultHead.next;\\n        }\\n        System.out.println(sb.toString().trim());\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\nclass ListNode:\\n    def __init__(self, x):\\n        self.val = x\\n        self.next = None\\n\\ndef remove_nth_from_end(head: ListNode, n: int) -> ListNode:\\n    dummy = ListNode(0)\\n    dummy.next = head\\n    fast = slow = dummy\\n    for _ in range(n + 1):\\n        fast = fast.next\\n    while fast:\\n        fast = fast.next\\n        slow = slow.next\\n    slow.next = slow.next.next\\n    return dummy.next\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    head = None\\n    if n > 0:\\n        nodes = list(map(int, lines[1].strip().split()))\\n        head = ListNode(nodes[0])\\n        tail = head\\n        for i in range(1, n):\\n            tail.next = ListNode(nodes[i])\\n            tail = tail.next\\n    x = int(lines[2].strip())\\n    result_head = remove_nth_from_end(head, x)\\n    res = []\\n    curr = result_head\\n    while curr:\\n        res.append(str(curr.val))\\n        curr = curr.next\\n    print(' '.join(res))\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction ListNode(val, next) {\\n    this.val = (val===undefined ? 0 : val)\\n    this.next = (next===undefined ? null : next)\\n}\\n\\nfunction removeNthFromEnd(head, n) {\\n    const dummy = new ListNode(0, head);\\n    let fast = dummy;\\n    let slow = dummy;\\n    for (let i = 0; i <= n; i++) {\\n        fast = fast.next;\\n    }\\n    while (fast) {\\n        fast = fast.next;\\n        slow = slow.next;\\n    }\\n    slow.next = slow.next.next;\\n    return dummy.next;\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [