382dc2a1-b065-4fca-90bb-68fe37157aee	Add Two Numbers	You are given two non-empty linked lists representing two non-negative integers. The digits are stored in reverse order, and each of their nodes contains a single digit. Add the two numbers and return the sum as a linked list in the same format. You may assume the two numbers do not contain any leading zero, except the number 0 itself.	MEDIUM	{"Linked List",Math,Recursion}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"display": {"input": "l1 = [2, 4, 3], l2 = [5, 6, 4]", "output": "[7, 0, 8]"}, "compiler": {"input": "3 3\\n2 4 3\\n5 6 4", "output": "7 0 8"}, "explanation": "342 + 465 = 807. In reverse order, this is [7, 0, 8]."}, {"display": {"input": "l1 = [9,9,9], l2 = [1]", "output": "[0,0,0,1]"}, "compiler": {"input": "3 1\\n9 9 9\\n1", "output": "0 0 0 1"}, "explanation": "999 + 1 = 1000. In reverse order, this is [0, 0, 0, 1]."}]	\N	[{"input": "3 3\\n2 4 3\\n5 6 4", "output": "7 0 8"}, {"input": "1 1\\n0\\n0", "output": "0"}, {"input": "7 3\\n9 9 9 9 9 9 9\\n9 9 9", "output": "8 9 9 0 0 0 0 1"}]	{"JAVA": {"template": "import java.util.*;\\n\\nclass ListNode {\\n    int val;\\n    ListNode next;\\n    ListNode(int x) { val = x; next = null; }\\n}\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    private static ListNode buildList(Scanner scanner, int n) {\\n        if (n == 0) return null;\\n        ListNode head = new ListNode(scanner.nextInt());\\n        ListNode tail = head;\\n        for (int i = 1; i < n; i++) {\\n            tail.next = new ListNode(scanner.nextInt());\\n            tail = tail.next;\\n        }\\n        return head;\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            int n = scanner.nextInt();\\n            int m = scanner.nextInt();\\n            ListNode list1 = buildList(scanner, n);\\n            ListNode list2 = buildList(scanner, m);\\n            \\n            Solution sol = new Solution();\\n            ListNode resultHead = sol.addTwoNumbers(list1, list2);\\n\\n            StringBuilder sb = new StringBuilder();\\n            while(resultHead != null) {\\n                sb.append(resultHead.val).append(\\" \\");\\n                resultHead = resultHead.next;\\n            }\\n            System.out.println(sb.toString().trim());\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {\\n        // Write your code here\\n        return null;\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass ListNode:\\n    def __init__(self, x):\\n        self.val = x\\n        self.next = None\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\ndef build_list(nodes_data):\\n    if not nodes_data:\\n        return None\\n    head = ListNode(nodes_data[0])\\n    tail = head\\n    for i in range(1, len(nodes_data)):\\n        tail.next = ListNode(nodes_data[i])\\n        tail = tail.next\\n    return head\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = [line.strip() for line in sys.stdin.readlines()]\\n        n, m = map(int, lines[0].split())\\n        \\n        list1_data = list(map(int, lines[1].split())) if n > 0 and len(lines) > 1 and lines[1] else []\\n        list2_data = list(map(int, lines[2].split())) if m > 0 and len(lines) > 2 and lines[2] else []\\n\\n        list1 = build_list(list1_data)\\n        list2 = build_list(list2_data)\\n\\n        sol = Solution()\\n        result_head = sol.addTwoNumbers(list1, list2)\\n        \\n        res = []\\n        curr = result_head\\n        while curr:\\n            res.append(str(curr.val))\\n            curr = curr.next\\n        print(' '.join(res))\\n\\n    except (IOError, ValueError, IndexError):\\n        pass", "userCode": "    def addTwoNumbers(self, l1: ListNode, l2: ListNode) -> ListNode:\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const 