ll || l2 != null || carry != 0) {\\n            int v1 = (l1 != null) ? l1.val : 0;\\n            int v2 = (l2 != null) ? l2.val : 0;\\n            int sum = v1 + v2 + carry;\\n            carry = sum / 10;\\n            curr.next = new ListNode(sum % 10);\\n            curr = curr.next;\\n            if (l1 != null) l1 = l1.next;\\n            if (l2 != null) l2 = l2.next;\\n        }\\n        return dummyHead.next;\\n    }\\n\\n    private static ListNode buildList(Scanner scanner, int n) {\\n        if (n == 0) return null;\\n        ListNode head = new ListNode(scanner.nextInt());\\n        ListNode tail = head;\\n        for (int i = 1; i < n; i++) {\\n            tail.next = new ListNode(scanner.nextInt());\\n            tail = tail.next;\\n        }\\n        return head;\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        int m = scanner.nextInt();\\n        ListNode list1 = buildList(scanner, n);\\n        ListNode list2 = buildList(scanner, m);\\n        ListNode resultHead = addTwoNumbers(list1, list2);\\n        StringBuilder sb = new StringBuilder();\\n        while(resultHead != null) {\\n            sb.append(resultHead.val).append(\\" \\");\\n            resultHead = resultHead.next;\\n        }\\n        System.out.println(sb.toString().trim());\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\nclass ListNode:\\n    def __init__(self, x):\\n        self.val = x\\n        self.next = None\\n\\ndef add_two_numbers(l1: ListNode, l2: ListNode) -> ListNode:\\n    dummy_head = ListNode(0)\\n    curr = dummy_head\\n    carry = 0\\n    while l1 or l2 or carry:\\n        v1 = l1.val if l1 else 0\\n        v2 = l2.val if l2 else 0\\n        total = v1 + v2 + carry\\n        carry = total // 10\\n        curr.next = ListNode(total % 10)\\n        curr = curr.next\\n        l1 = l1.next if l1 else None\\n        l2 = l2.next if l2 else Non