put: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const [n, m] = lines[0].split(' ').map(Number);\\n    const list1_values = n > 0 && lines.length > 1 && lines[1] ? lines[1].split(' ').map(Number) : [];\\n    const list2_values = m > 0 && lines.length > 2 && lines[2] ? lines[2].split(' ').map(Number) : [];\\n    const list1 = buildList(list1_values);\\n    const list2 = buildList(list2_values);\\n    const resultHead = addTwoNumbers(list1, list2);\\n    const result = [];\\n    let current = resultHead;\\n    while(current) {\\n        result.push(current.val);\\n        current = current.next;\\n    }\\n    console.log(result.join(' '));\\n});"}	2025-07-31 20:00:43.33	2025-07-31 20:00:43.33	["The number of nodes in each linked list is in the range [1, 1000].", "0 <= Node.val <= 9"]	{Amazon,Flipkart,MakeMyTrip,Microsoft,"Morgan Stanley",Qualcomm,Snapdeal}	\N
f63fe284-7cdc-4ec3-b2d8-832821380c04	Palindrome Linked List	Given the `head` of a singly linked list, determine if it is a palindrome. A palindrome is a sequence that reads the same backward as forward.	EASY	{"Linked List","Two Pointers",Recursion}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"display": {"input": "head = [1, 2, 2, 1]", "output": "1"}, "compiler": {"input": "4\\n1 2 2 1", "output": "1"}, "explanation": "The sequence 1-2-2-1 is a palindrome."}, {"display": {"input": "head = [1, 2]", "output": "0"}, "compiler": {"input": "2\\n1 2", "output": "0"}, "explanation": "The sequence 1-2 is not a palindrome."}]	\N	[{"input": "4\\n1 2 2 1", "output": "1"}, {"input": "4\\n1 2 3 1", "output": "0"}, {"input": "1\\n9", "output": "1"}, {"input": "5\\n1 2 3 2 1", "output": "1"}]	{"JAVA": {"template": "import java.util.*;\\n\\nclass ListNode {\\n    int val;\\n    ListNode next;\\n    ListNode(int x) { val = x; next = null; }\\n}\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            int n = scanner.nextInt();\\n            ListNode head = null;\\n            if (n > 0) {\\n                ListNode tail;\\n                head = new ListNode(scanner.nextInt());\\n                tail = head;\\n                for (int i = 1; i < n; i++) {\\n                    tail.next = new ListNode(scanner.nextInt());\\n                    tail = tail.next;\\n                }\\n            }\\n            Solution sol = new Solution();\\n            boolean isPal = sol.isPalindrome(head);\\n            System.out.println(isPal ? 1 : 0);\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    public boolean isPalindrome(ListNode head) {\\n        // Write your code here\\n        return false;\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass ListNode:\\n    def __init__(self, x):\\n        self.val = x\\n        self.next = None\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = sys.stdin.readlines()\\n        n = int(lines[0].strip())\\n        head = None\\n        if n > 0:\\n            nodes = list(map(int, lines[1].strip().split()))\\n            head = ListNode(nodes[0])\\n            tail = head\\n            for i in range(1, n):\\n                tail.next = ListNode(nodes[i])\\n                tail = tail.next\\n        \\n        sol = Solution()\\n        is_pal = sol.isPalindrome(head)\\n        print(1 if is_pal else 0)\\n\\n    except (IOError, ValueError, IndexError):\\n        pass", "userCode": "    def isPalindrome(self, head: ListNode) -> bool:\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\nfunction ListNode(val, next) {\\n    this.val = (val===undefined ? 0 : val)\\n    this.next = (next===undefined ? null : next)\\n}\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const n = parseInt(lines[0], 10);\\n        let head = null;\\n        if (n > 0) {\\n            const values = lines[1].split(' ').map(Number);\\n            let current = head = new ListNode(values[0]);\\n            for (let i = 1; i < n; i++) {\\n                current.next = new ListNode(values[i]);\\n                current = current.next;\\n            }\\n        }\\n        const isPal = isPalindrome(head);\\n        console.log(isPal ? 1 : 0);\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {ListNode} head\\n * @return {boolean}\\n */\\nvar isPalindrome = function(head) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\nclass ListNode {\\n    int val;\\n    ListNode next;\\n    ListNode(int x) { val = x; next = null; }\\n}\\n\\npublic class Main {\\n    public static ListNode reverseList(ListNode head) {\\n        ListNode prev = null;\\n        ListNode curr = head;\\n        while (curr != null) {\\n            ListNode nextTemp = curr.next;\\n            curr.next = prev;\\n            prev = curr;\\n            curr = nextTemp;\\n        }\\n        return prev;\\n    }\\n\\n    public static ListNode findMiddle(ListNode head) {\\n        ListNode slow = head;\\n        ListNode fast = head;\\n        while (fast.next != null && fast.next.next != null) {\\n            slow = slow.next;\\n            fast = fast.next.next;\\n        }\\n        return slow;\\n    }\\n\\n    public static boolean isPalindrome(ListNode head) {\\n        if (head == null || head.next == null) return true;\\n        ListNode middle = findMiddle(head);\\n        ListNode secondHalf = reverseList(middle.next);\\n        ListNode p1 = head;\\n        ListNode p2 = secondHalf;\\n        boolean result = true;\\n        while (result && p2 != null) {\\n            if (p1.val != p2.val) result = false;\\n            p1 = p1.next;\\n            p2 = p2.next;\\n        }\\n        middle.next = reverseList(secondHalf);\\n        return result;\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        ListNode head = null;\\n        if (n > 0) {\\n            ListNode tail;\\n            head = new ListNode(scanner.nextInt());\\n            tail = head;\\n            for (int i = 1; i < n; i++) {\\n                tail.next = new ListNode(scanner.nextInt());\\n                tail = tail.next;\\n            }\\n        }\\n        boolean isPal = isPalindrome(head);\\n        System.out.println(isPal ? 1 : 0);\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\nclass ListNode:\\n    def __init__(self, x):\\n        self.val = x\\n        self.next = None\\n\\ndef reverse_list(head):\\n    prev = None\\n    curr = head\\n    while curr:\\n        next_temp = curr.next\\n        curr.next = prev\\n        prev = curr\\n        curr = next_temp\\n    return prev\\n\\ndef find_middle(head):\\n    slow = head\\n    fast = head\\n    while fast.next and fast.next.next:\\n        slow = slow.next\\n        fast = fast.next.next\\n    return slow\\n\\ndef is_palindrome(head: ListNode) -> bool:\\n    if not head or not head.next:\\n        return True\\n    \\n    middle = find_middle(head)\\n    second_half_start = reverse_list(middle.next)\\n    \\n    p1 = head\\n    p2 = second_half_start\\n    result = True\\n    while result and p2:\\n        if p1.val != p2.val:\\n            result = False\\n        p1 = p1.next\\n        p2 = p2.next\\n        \\n    middle.next = reverse_list(second_half_start) # Restore list\\n    return result\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    head = None\\n    if n > 0:\\n        nodes = list(map(int, lines[1].strip().split()))\\n        head = ListNode(nodes[0])\\n        tail = head\\n        for i in range(1, n):\\n            tail.next = ListNode(nodes[i])\\n            tail = tail.next\\n    \\n    is_pal = is_palindrome(head)\\n    print(1 if is_pal else 0)\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction ListNode(val, next) {\\n    this.val = (val===undefined ? 0 : val)\\n    this.next = (next===undefined ? null : next)\\n}\\n\\nfunction reverseList(head) {\\n    let prev = null;\\n    let curr = head;\\n    while (curr) {\\n        const nextTemp = curr.next;\\n        curr.next = prev;\\n        prev = curr;\\n        curr = nextTemp;\\n    }\\n    return prev;\\n}\\n\\nfunction findMiddle(head) {\\n    let slow = head;\\n    let fast = head;\\n    while (fast.next && fast.next.next) {\\n        slow = slow.next;\\n        fast = fast.next.next;\\n    }\\n    return slow;\\n}\\n\\nfunction isPalindrome(head) {\\n    if (!head || !head.next) return true;\\n\\n    const middle = findMiddle(head);\\n    let secondHalf = reverseList(middle.next);\\n    \\n    let p1 = head;\\n    let p2 = secondHalf;\\n    let result = true;\\n    while (result && p2) {\\n        if (p1.val !== p2.val) result = false;\\n        p1 = p1.next;\\n        p2 = p2.next;\\n    }\\n    \\n    middle.next = reverseList(secondHalf); // Restore list\\n    return result;\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const n = parseInt(lines[0], 10);\\n    let head = null;\\n    if (n > 0) {\\n        const values = lines[1].split(' ').map(Number);\\n        let current = head = new ListNode(values[0]);\\n        for (let i = 1; i < n; i++) {\\n            current.next = new ListNode(values[i]);\\n            current = current.next;\\n        }\\n    }\\n    const isPal = isPalindrome(head);\\n    console.log(isPal ? 1 : 0);\\n});"}	2025-07-31 20:01:53.872	2025-07-31 20:01:53.872	["The number of nodes in the list is in the range [1, 10000].", "0 <= Node.val <= 9"]	{Adobe,Amazon,Microsoft,Snapdeal,Facebook}	\N
c7452687-817c-4a6b-b603-ed4bf7b48403	Linked List Cycle II	Given the `head` of a linked list, return the node where the cycle begins. A cycle exists if some node in the list can be reached again by continuously following the `next` pointer. If there is no cycle, return `null`.	MEDIUM	{"Linked List","Two Pointers","Hash Table"}	f8b12c1f-f3ee-40da-8c52-221e9b23e0f8	[{"display": {"input": "head = [3,2,0,-4], pos = 1", "output": "Node with value 2"}, "compiler": {"input": "4\\n3 2 0 -4\\n1", "output": "2"}, "explanation": "There is a cycle in the linked list, where the tail connects to the 1st index (0-indexed) node, which has a value of 2."}, {"display": {"input": "head = [1,2], pos = 0", "output": "Node with value 1"}, "compiler": {"input": "2\\n1 2\\n0", "output": "1"}, "explanation": "The tail connects to the head of the list."}, {"display": {"input": "head = [1], pos = -1", "output": "null"}, "compiler": {"input": "1\\n1\\n-1", "output": "-1"}, "explanation": "There is no cycle in the linked list."}]	\N	[{"input": "4\\n3 2 0 -4\\n1", "output": "2"}, {"input": "2\\n1 2\\n0", "output": "1"}, {"input": "1\\n1\\n-1", "output": "-1"}, {"input": "0\\n\\n-1", "output": "-1"}]	{"JAVA": {"template": "import java.util.*;\\n\\nclass ListNode {\\n    int val;\\n    ListNode next;\\n    ListNode(int x) { val = x; next = null; }\\n}\\n\\nclass Main {\\n\\n// [USER_CODE_HERE]\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        try {\\n            int n = scanner.nextInt();\\n            ListNode head = null;\\n            ListNode[] nodes = new ListNode[n];\\n            if (n > 0) {\\n                for (int i = 0; i < n; i++) {\\n                    nodes[i] = new ListNode(scanner.nextInt());\\n                }\\n                for (int i = 0; i < n - 1; i++) {\\n                    nodes[i].next = nodes[i+1];\\n                }\\n                head = nodes[0];\\n            }\\n            int m = scanner.nextInt();\\n            if (m != -1 && n > 0) {\\n                nodes[n-1].next = nodes[m];\\n            }\\n            Solution sol = new Solution();\\n            ListNode resultNode = sol.detectCycle(head);\\n            System.out.println(resultNode != null ? resultNode.val : -1);\\n        } finally {\\n            scanner.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    public ListNode detectCycle(ListNode head) {\\n        // Write your code here\\n        return null;\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass ListNode:\\n    def __init__(self, x):\\n        self.val = x\\n        self.next = None\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = sys.stdin.readlines()\\n        n = int(lines[0].strip())\\n        head = None\\n        if n > 0:\\n            values = list(map(int, lines[1].strip().split()))\\n            nodes = [ListNode(v) for v in values]\\n            for i in range(n - 1):\\n                nodes[i].next = nodes[i+1]\\n            head = nodes[0]\\n            m = int(lines[2].strip())\\n            if m != -1:\\n                nodes[n-1].next = nodes[m]\\n        \\n        sol = Solution()\\n        result_node = sol.detectCycle(head)\\n        print(result_node.val if result_node else -1)\\n\\n    except (IOError, ValueError, IndexError):\\n        print(-1)", "userCode": "    def detectCycle(self, head: ListNode) -> ListNode:\\n        # Write your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\nfunction ListNode(val) {\\n    this.val = val;\\n    this.next = null;\\n}\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const n = parseInt(lines[0], 10);\\n        let head = null;\\n        if (n > 0) {\\n            const values = lines[1].split(' ').map(Number);\\n            const nodes = values.map(v => new ListNode(v));\\n            for (let i = 0; i < n - 1; i++) {\\n                nodes[i].next = nodes[i+1];\\n            }\\n            head = nodes[0];\\n            const m = parseInt(lines[2], 10);\\n            if (m !== -1) {\\n                nodes[n-1].next = nodes[m];\\n            }\\n        }\\n        const resultNode = detectCycle(head);\\n        console.log(resultNode ? resultNode.val : -1);\\n    } catch (e) {\\n        console.log(-1);\\n    }\\n});", "userCode": "/**\\n * @param {ListNode} head\\n * @return {ListNode}\\n */\\nvar detectCycle = function(head) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\nclass ListNode {\\n    int val;\\n    ListNode next;\\n    ListNode(int x) { val = x; next = null; }\\n}\\n\\npublic class Main {\\n    public static ListNode detectCycle(ListNode head) {\\n        if (head == null || head.next == null) return null;\\n        ListNode slow = head;\\n        ListNode fast = head;\\n        while (fast != null && fast.next != null) {\\n            slow = slow.next;\\n            fast = fast.next.next;\\n            if (slow == fast) {\\n                slow = head;\\n                while (slow != fast) {\\n                    slow = slow.next;\\n                    fast = fast.next;\\n                }\\n                return slow;\\n            }\\n        }\\n        return null;\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        ListNode head = null;\\n        ListNode[] nodes = new ListNode[n];\\n        if (n > 0) {\\n            for (int i = 0; i < n; i++) {\\n                nodes[i] = new ListNode(scanner.nextInt());\\n            }\\n            for (int i = 0; i < n - 1; i++) {\\n                nodes[i].next = nodes[i+1];\\n            }\\n            head = nodes[0];\\n        }\\n        int m = scanner.nextInt();\\n        if (m != -1 && n > 0) {\\n            nodes[n-1].next = nodes[m];\\n        }\\n        ListNode resultNode = detectCycle(head);\\n        System.out.println(resultNode != null ? resultNode.val : -1);\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\nclass ListNode:\\n    def __init__(self, x):\\n        self.val = x\\n        self.next = None\\n\\ndef detect_cycle(head: ListNode) -> ListNode:\\n    slow = fast = head\\n    while fast and fast.next:\\n        slow = slow.next\\n        fast = fast.next.next\\n        if slow == fast:\\n            slow = head\\n            while slow != fast:\\n                slow = slow.next\\n                fast = fast.next\\n            return slow\\n    return None\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    head = None\\n    if n > 0:\\n        values = list(map(int, lines[1].strip().split()))\\n        nodes = [ListNode(v) for v in values]\\n        for i in range(n - 1):\\n            nodes[i].next = nodes[i+1]\\n        head = nodes[0]\\n        m = int(lines[2].strip())\\n        if m != -1:\\n            nodes[n-1].next = nodes[m]\\n    result_node = detect_cycle(head)\\n    print(result_node.val if result_node else -1)\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction ListNode(val) {\\n    this.val = val;\\n    this.next = null;\\n}\\n\\nfunction detectCycle(head) {\\n    if (!head || !head.next) return null;\\n    let slow = head, fast = head;\\n    while (fast && fast.next) {\\n        slow = slow.next;\\n        fast = fast.next.next;\\n        if (slow === fast) {\\n            slow = head;\\n            while (slow !== fast) {\\n                slow = slow.next;\\n                fast = fast.next;\\n            }\\n            return slow;\\n        }\\n    }\\n    return null;\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    let head = null;\\n    try {\\n        const n = parseInt(lines[0] || '0', 10);\\n        if (n > 0) {\\n            const values = lines[1].split(' ').map(Number);\\n            const nodes = values.map(v => new ListNode(v));\\n            for (let i = 0; i < n - 1; i++) {\\n                nodes[i].next = nodes[i+1];\\n            }\\n            head = nodes[0];\\n            const m = parseInt(lines[2], 10);\\n            if (m !== -1) {\\n                nodes[n-1].next = nodes[m];\\n            }\\n        }\\n        const resultNode = detectCycle(head);\\n        console.log(resultNode ? resultNode.val : -1);\\n    } catch(e) {\\n        console.log(-1);\\n    }\\n});"}	2025-07-31 20:03:54.15	2025-07-31 20:03:54.15	["The number of the nodes in the list is in the range [0, 10000].", "-100000 <= Node.val <= 100000", "`pos` is -1 or a valid index in the linked list."]	{Amazon,MakeMyTrip,Oyo,Paytm,Qualcomm,Samsung,Snapdeal}	\N
