ode = new Node(Integer.parseInt(val));\\n                    if (vHead == null) {\\n                        vHead = vTail = newNode;\\n                    } else {\\n                        vTail.bottom = newNode;\\n                        vTail = newNode;\\n                    }\\n                }\\n                if (head == null) {\\n                    head = tail = vHead;\\n                } else {\\n                    tail.next = vHead;\\n                    tail = vHead;\\n                }\\n            }\\n            Solution sol = new Solution();\\n            Node resultHead = sol.flatten(head);\\n            StringBuilder sb = new StringBuilder();\\n            while(resultHead != null) {\\n                sb.append(resultHead.data).append(\\" \\");\\n                resultHead = resultHead.bottom;\\n            }\\n            System.out.println(sb.toString().trim());\\n        } finally {\\n            sc.close();\\n        }\\n    }\\n}", "userCode": "class Solution {\\n    Node flatten(Node root) {\\n        // Your code here\\n        return null;\\n    }\\n}"}, "PYTHON": {"template": "import sys\\n\\nclass Node:\\n    def __init__(self, d):\\n        self.data = d\\n        self.next = None\\n        self.bottom = None\\n\\nclass Solution:\\n# [USER_CODE_HERE]\\n\\nif __name__ == '__main__':\\n    try:\\n        lines = [line.strip() for line in sys.stdin.readlines() if line.strip()]\\n        n = int(lines[0])\\n        lengths = list(map(int, lines[1].split()))\\n        \\n        head, tail = None, None\\n        line_idx = 2\\n        for i in range(n):\\n            values = list(map(int, lines[line_idx].split()))\\n            line_idx += 1\\n            v_head, v_tail = None, None\\n            for val in values:\\n                new_node = Node(val)\\n                if not v_head:\\n                    v_head = v_tail = new_node\\n                else:\\n                    v_tail.bottom = new_node\\n                    v_tail = new_node\\n            \\n            if not head:\\n                head = tail = v_head\\n            else:\\n                tail.next = v_head\\n                tail = v_head\\n\\n        sol = Solution()\\n        result_head = sol.flatten(head)\\n        \\n        res = []\\n        curr = result_head\\n        while curr:\\n            res.append(str(curr.data))\\n            curr = curr.bottom\\n        print(' '.join(res))\\n\\n    except (IOError, ValueError, IndexError):\\n        pass", "userCode": "    def flatten(self, root):\\n        # Your code here\\n        pass"}, "JAVASCRIPT": {"template": "const readline = require('readline');\\n\\nfunction Node(data) {\\n    this.data = data;\\n    this.next = null;\\n    this.bottom = null;\\n}\\n\\n// [USER_CODE_HERE]\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        lines = lines.filter(line => line.trim() !== '');\\n        const n = parseInt(lines[0], 10);\\n        const lengths = lines[1].split(' ').map(Number);\\n        let head = null, tail = null;\\n        let lineIdx = 2;\\n        for(let i=0; i<n; i++) {\\n            const values = lines[lineIdx++].split(' ').map(Number);\\n            let vHead = null, vTail = null;\\n            values.forEach(val => {\\n                const newNode = new Node(val);\\n                if (!vHead) {\\n                    vHead = vTail = newNode;\\n                } else {\\n                    vTail.bottom = newNode;\\n                    vTail = newNode;\\n                }\\n            });\\n            if (!head) {\\n                head = tail = vHead;\\n            } else {\\n                tail.next = vHead;\\n                tail = vHead;\\n            }\\n        }\\n\\n        const resultHead = flatten(head);\\n        const result = [];\\n       