sh(current.data);\\n        current = current.bottom;\\n    }\\n    console.log(result.join(' '));\\n});"}	2025-07-31 20:04:44.489	2025-07-31 20:04:44.489	["1 <= n <= 100", "1 <= Li <= 100", "1 <= node value <= 1000"]	{Amazon,Flipkart,"Goldman Sachs",Microsoft,Paytm,Qualcomm,Snapdeal,Visa}	\N
