\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    try {\\n        const n = parseInt(lines[0], 10);\\n        let head = null;\\n        if (n > 0) {\\n            const values = lines[1].split(' ').map(Number);\\n            let current = head = new ListNode(values[0]);\\n            for (let i = 1; i < n; i++) {\\n                current.next = new ListNode(values[i]);\\n                current = current.next;\\n            }\\n        }\\n        const [left, right] = lines[2].split(' ').map(Number);\\n        const resultHead = reverseBetween(head, left, right);\\n        const result = [];\\n        let current = resultHead;\\n        while(current) {\\n            result.push(current.val);\\n            current = current.next;\\n        }\\n        console.log(result.join(' '));\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {ListNode} head\\n * @param {number} left\\n * @param {number} right\\n * @return {ListNode}\\n */\\nvar reverseBetween = function(head, left, right) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\nclass ListNode {\\n    int val;\\n    ListNode next;\\n    ListNode(int x) { val = x; next = null; }\\n}\\n\\npublic class Main {\\n    public static ListNode reverseBetween(ListNode head, int left, int right) {\\n        if (head == null || left == right) return head;\\n        ListNode dummy = new ListNode(0);\\n        dummy.next = head;\\n        ListNode preLeft = dummy;\\n        for (int i = 0; i < left - 1; i++) {\\n            preLeft = preLeft.next;\\n        }\\n        ListNode curr = preLeft.next;\\n        ListNode prev = null;\\n        for (int i = 0; i < right - left + 1; i++) {\\n            ListNode nextNode = curr.next;\\n            curr.next = prev;\\n            prev = curr;\\n            curr = nextNode;\\n        }\\n        preLeft.next.next = curr;\\n        preLeft.next = prev;\\n        return dummy.next;\\n    }\\n\\