; i++) {\\n                current.next = new ListNode(values[i]);\\n                current = current.next;\\n            }\\n        }\\n        const resultHead = plusOne(head);\\n        const result = [];\\n        let current = resultHead;\\n        while(current) {\\n            result.push(current.val);\\n            current = current.next;\\n        }\\n        console.log(result.join(' '));\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {ListNode} head\\n * @return {ListNode}\\n */\\nvar plusOne = function(head) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\nclass ListNode {\\n    int val;\\n    ListNode next;\\n    ListNode(int x) { val = x; next = null; }\\n}\\n\\npublic class Main {\\n    public static ListNode reverse(ListNode head) {\\n        ListNode prev = null;\\n        ListNode curr = head;\\n        while (curr != null) {\\n            ListNode nextNode = curr.next;\\n            curr.next = prev;\\n            prev = curr;\\n            curr = nextNode;\\n        }\\n        return prev;\\n    }\\n\\n    public static ListNode plusOne(ListNode head) {\\n        ListNode reversedHead = reverse(head);\\n        ListNode curr = reversedHead;\\n        int carry = 1;\\n\\n        while (curr != null && carry > 0) {\\n            int sum = curr.val + carry;\\n            curr.val = sum % 10;\\n            carry = sum / 10;\\n            if (curr.next == null && carry > 0) {\\n                curr.next = new ListNode(carry);\\n                carry = 0;\\n            }\\n            curr = curr.next;\\n        }\\n\\n        return reverse(reversedHead);\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        ListNode head = null;\\n        if (n > 0) {\\n            ListNode tail;\\n            head = new ListNode(scanner.nextInt());\\n            tail = head;\\n            for (int i = 1; i < n; i++) {\\n                tail.next = new ListNode(scanner.nextInt());\\n                tail = tail.next;\\n            }\\n        }\\n        ListNode resultHead = plusOne(head);\\n        StringBuilder sb = new StringBuilder();\\n        while(resultHead != null) {\\n            sb.append(resultHead.val).append(\\" \\");\\n            resultHead = resultHead.next;\\n        }\\n        System.out.println(sb.toString().trim());\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\nclass ListNode:\\n    def __init__(self, x):\\n        self.val = x\\n        self.next = None\\n\\ndef reverse(head):\\n    prev = None\\n    curr = head\\n    while curr:\\n        next_node = curr.next\\n        curr.next = prev\\n        prev = curr\\n        curr = next_node\\n    return prev\\n\\ndef plus_one(head: ListNode) -> ListNode:\\n    reversed_head = reverse(head)\\n    curr = reversed_head\\n    carry = 1\\n\\n    while curr and carry > 0:\\n        total = curr.val + carry\\n        curr.val = total % 10\\n        carry = total // 10\\n        if not curr.next and carry > 0:\\n            curr.next = ListNode(carry)\\n            carry = 0\\n        curr = curr.next\\n\\n    return reverse(reversed_head)\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    head = None\\n    if n > 0:\\n        nodes = list(map(int, lines[1].strip().split()))\\n        head = ListNode(nodes[0])\\n        tail = head\\n        for i in range(1, n):\\n            tail.next = ListNode(nodes[i])\\n            tail = tail.next\\n    result_head = plus_one(head)\\n    res = []\\n    curr = result_head\\n    while curr:\\n        res.append(str(curr.val))\\n        curr = curr.next\\n    print(' '.join(res))\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction ListNode(val, next) {\\n    this.val = (val===undefined ? 0 : val)\\n    this.next = (next===undefined ? null : next)\\n}\\n\\nfunction reverse(head) {\\n    let prev = null;\\n    let curr = head;\\n    while (curr) {\\n        const nextNode = curr.next;\\n        curr.next = prev;\\n        prev = curr;\\n        curr = nextNode;\\n    }\\n    return prev;\\n}\\n\\nfunction plusOne(head) {\\n    const reversedHead = reverse(head);\\n    let curr = reversedHead;\\n    let carry = 1;\\n\\n    while (curr && carry > 0) {\\n        const sum = curr.val + carry;\\n        curr.val = sum % 10;\\n        carry = Math.floor(sum / 10);\\n        if (!curr.next && carry > 0) {\\n            curr.next = new ListNode(carry);\\n            carry = 0;\\n        }\\n        curr = curr.next;\\n    }\\n    return reverse(reversedHead);\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const n = parseInt(lines[0], 10);\\n    let head = null;\\n    if (n > 0) {\\n        const values = lines[1].split(' ').map(Number);\\n        let current = head = new ListNode(values[0]);\\n        for (let i = 1; i < n; i++) {\\n            current.next = new ListNode(values[i]);\\n            current = current.next;\\n        }\\n    }\\n    const resultHead = plusOne(head);\\n    const result = [];\\n    let current = resultHead;\\n    while(current) {\\n        result.push(current.val);\\n        current = current.next;\\n    }\\n    console.log(result.join(' '));\\n});"}	2025-07-31 20:08:48.395	2025-07-31 20:08:48.395	["The number of nodes in the linked list is in the range [1, 10000].", "0 <= Node.val <= 9"]	{Amazon,Microsoft,Google}	\N
