nt(lines[0], 10);\\n        let head = null;\\n        if (n > 0) {\\n            const values = lines[1].split(' ').map(Number);\\n            let current = head = new ListNode(values[0]);\\n            for (let i = 1; i < n; i++) {\\n                current.next = new ListNode(values[i]);\\n                current = current.next;\\n            }\\n        }\\n        reorderList(head);\\n        const result = [];\\n        let current = head;\\n        while(current) {\\n            result.push(current.val);\\n            current = current.next;\\n        }\\n        console.log(result.join(' '));\\n    } catch (e) {}\\n});", "userCode": "/**\\n * @param {ListNode} head\\n * @return {void} Do not return anything, modify head in-place instead.\\n */\\nvar reorderList = function(head) {\\n    // Write your code here\\n};"}}	{"JAVA": "import java.util.*;\\n\\nclass ListNode {\\n    int val;\\n    ListNode next;\\n    ListNode(int x) { val = x; next = null; }\\n}\\n\\npublic class Main {\\n    public static void reorderList(ListNode head) {\\n        if (head == null || head.next == null) return;\\n\\n        // Find middle\\n        ListNode slow = head, fast = head;\\n        while (fast.next != null && fast.next.next != null) {\\n            slow = slow.next;\\n            fast = fast.next.next;\\n        }\\n\\n        // Reverse second half\\n        ListNode prev = null, curr = slow.next;\\n        while (curr != null) {\\n            ListNode nextNode = curr.next;\\n            curr.next = prev;\\n            prev = curr;\\n            curr = nextNode;\\n        }\\n        slow.next = null;\\n\\n        // Merge lists\\n        ListNode first = head, second = prev;\\n        while (second != null) {\\n            ListNode temp1 = first.next;\\n            ListNode temp2 = second.next;\\n            first.next = second;\\n            second.next = temp1;\\n            first = temp1;\\n            second = temp2;\\n        }\\n    }\\n\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int n = scanner.nextInt();\\n        ListNode head = null;\\n        if (n > 0) {\\n            ListNode tail;\\n            head = new ListNode(scanner.nextInt());\\n            tail = head;\\n            for (int i = 1; i < n; i++) {\\n                tail.next = new ListNode(scanner.nextInt());\\n                tail = tail.next;\\n            }\\n        }\\n        reorderList(head);\\n        StringBuilder sb = new StringBuilder();\\n        while(head != null) {\\n            sb.append(head.val).append(\\" \\");\\n            head = head.next;\\n        }\\n        System.out.println(sb.toString().trim());\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\nclass ListNode:\\n    def __init__(self, x):\\n        self.val = x\\n        self.next = None\\n\\ndef reorder_list(head: ListNode) -> None:\\n    if not head or not head.next:\\n        return\\n\\n    # Find middle\\n    slow, fast = head, head\\n    while fast.next and fast.next.next:\\n        slow = slow.next\\n        fast = fast.next.next\\n\\n    # Reverse second half\\n    prev, curr = None, slow.next\\n    slow.next = None\\n    while curr:\\n        next_node = curr.next\\n        curr.next = prev\\n        prev = curr\\n        curr = next_node\\n\\n    # Merge\\n    first, second = head, prev\\n    while second:\\n        temp1, temp2 = first.next, second.next\\n        first.next = second\\n        second.next = temp1\\n        first, second = temp1, temp2\\n\\ndef solve():\\n    lines = sys.stdin.readlines()\\n    n = int(lines[0].strip())\\n    head = None\\n    if n > 0:\\n        nodes = list(map(int, lines[1].strip().split()))\\n        head = ListNode(nodes[0])\\n        tail = head\\n        for i in range(1, n):\\n            tail.next = ListNode(nodes[i])\\n            tail = tail.next\\n    reorder_list(head)\\n    res = []\\n    curr = head\\n    while curr:\\n        res.append(str(curr.val))\\n        curr = curr.next\\n    print(' '.join(res))\\n\\nsolve()", "JAVASCRIPT": "const readline = require('readline');\\n\\nfunction ListNode(val, next) {\\n    this.val = (val===undefined ? 0 : val)\\n    this.next = (next===undefined ? null : next)\\n}\\n\\nfunction reorderList(head) {\\n    if (!head || !head.next) return;\\n\\n    // Find middle\\n    let slow = head, fast = head;\\n    while (fast.next && fast.next.next) {\\n        slow = slow.next;\\n        fast = fast.next.next;\\n    }\\n\\n    // Reverse second half\\n    let prev = null, curr = slow.next;\\n    slow.next = null;\\n    while (curr) {\\n        const nextNode = curr.next;\\n        curr.next = prev;\\n        prev = curr;\\n        curr = nextNode;\\n    }\\n\\n    // Merge\\n    let first = head, second = prev;\\n    while (second) {\\n        const temp1 = first.next;\\n        const temp2 = second.next;\\n        first.next = second;\\n        second.next = temp1;\\n        first = temp1;\\n        second = temp2;\\n    }\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const n = parseInt(lines[0], 10);\\n    let head = null;\\n    if (n > 0) {\\n        const values = lines[1].split(' ').map(Number);\\n        let current = head = new ListNode(values[0]);\\n        for (let i = 1; i < n; i++) {\\n            current.next = new ListNode(values[i]);\\n            current = current.next;\\n        }\\n    }\\n    reorderList(head);\\n    const result = [];\\n    let current = head;\\n    while(current) {\\n        result.push(current.val);\\n        current = current.next;\\n    }\\n    console.log(result.join(' '));\\n});"}	2025-07-31 20:09:09.543	2025-07-31 20:09:09.543	["The number of nodes in the list is in the range [1, 10000].", "1 <= Node.val <= 1000"]	{Amazon,Microsoft,Oyo