ement here\\n        return -1;\\n    }\\n\\n    size() {\\n        // Implement here\\n        return 0;\\n    }\\n\\n    isEmpty() {\\n        // Implement here\\n        return true;\\n    }\\n}"}}	{"JAVA": "import java.util.*;\\n\\nclass MyQueue {\\n    private int[] arr;\\n    private int front;\\n    private int rear;\\n    private int size;\\n    private int capacity;\\n\\n    public MyQueue() {\\n        capacity = 1001; // As per constraints\\n        arr = new int[capacity];\\n        front = 0;\\n        rear = -1;\\n        size = 0;\\n    }\\n    \\n    public void push(int x) {\\n        if (size < capacity) {\\n            rear = (rear + 1) % capacity;\\n            arr[rear] = x;\\n            size++;\\n        }\\n    }\\n    \\n    public void pop() {\\n        if (size > 0) {\\n            front = (front + 1) % capacity;\\n            size--;\\n        }\\n    }\\n    \\n    public int front() {\\n        if (size == 0) return -1;\\n        return arr[front];\\n    }\\n\\n    public int back() {\\n        if (size == 0) return -1;\\n        return arr[rear];\\n    }\\n    \\n    public int size() {\\n        return size;\\n    }\\n\\n    public boolean isEmpty() {\\n        return size == 0;\\n    }\\n}\\n\\nclass Main {\\n    public static void main(String[] args) {\\n        Scanner scanner = new Scanner(System.in);\\n        int q = Integer.parseInt(scanner.nextLine());\\n        MyQueue queue = new MyQueue();\\n        for (int i = 0; i < q; i++) {\\n            String[] op = scanner.nextLine().split(\\" \\");\\n            switch (op[0]) {\\n                case \\"push\\":\\n                    queue.push(Integer.parseInt(op[1]));\\n                    break;\\n                case \\"pop\\":\\n                    queue.pop();\\n                    break;\\n                case \\"front\\":\\n                    System.out.println(queue.front());\\n                    break;\\n                case \\"back\\":\\n                    System.out.println(queue.back());\\n                    break;\\n                case \\"size\\":\\n                    System.out.println(queue.size());\\n                    break;\\n                case \\"isEmpty\\":\\n                    System.out.println(queue.isEmpty());\\n                    break;\\n            }\\n        }\\n        scanner.close();\\n    }\\n}", "PYTHON": "import sys\\n\\nclass MyQueue:\\n    def __init__(self):\\n        self.capacity = 1001\\n        self.arr = [0] * self.capacity\\n        self.front_idx = 0\\n        self.rear_idx = -1\\n        self.current_size = 0\\n\\n    def push(self, x: int) -> None:\\n        if self.current_size < self.capacity:\\n            self.rear_idx = (self.rear_idx + 1) % self.capacity\\n            self.arr[self.rear_idx] = x\\n            self.current_size += 1\\n\\n    def pop(self) -> None:\\n        if self.current_size > 0:\\n            self.front_idx = (self.front_idx + 1) % self.capacity\\n            self.current_size -= 1\\n\\n    def front(self) -> int:\\n        if self.current_size == 0:\\n            return -1\\n        return self.arr[self.front_idx]\\n\\n    def back(self) -> int:\\n        if self.current_size == 0:\\n            return -1\\n        return self.arr[self.rear_idx]\\n\\n    def size(self) -> int:\\n        return self.current_size\\n\\n    def isEmpty(self) -> bool:\\n        return self.current_size == 0\\n\\ndef solve():\\n    lines = [line.strip() for line in sys.stdin.readlines()]\\n    q = int(lines[0])\\n    queue = MyQueue()\\n    for i in range(1, q + 1):\\n        op = lines[i].split()\\n        cmd = op[0]\\n        if cmd == 'push':\\n            queue.push(int(op[1]))\\n        elif cmd == 'pop':\\n            queue.pop()\\n        elif cmd == 'front':\\n            print(queue.front())\\n        elif cmd == 'back':\\n            print(queue.back())\\n        elif cmd == 'size':\\n            print(queue.size())\\n        elif cmd == 'isEmpty':\\n            print(str(queue.isEmpty()).lower())\\n\\nsolve()", "JAVASCRIPT": "class MyQueue {\\n    constructor() {\\n        this.capacity = 1001;\\n        this.arr = new Array(this.capacity);\\n        this.frontIdx = 0;\\n        this.rearIdx = -1;\\n        this.currentSize = 0;\\n    }\\n\\n    push(x) {\\n        if (this.currentSize < this.capacity) {\\n            this.rearIdx = (this.rearIdx + 1) % this.capacity;\\n            this.arr[this.rearIdx] = x;\\n            this.currentSize++;\\n        }\\n    }\\n\\n    pop() {\\n        if (this.currentSize > 0) {\\n            this.frontIdx = (this.frontIdx + 1) % this.capacity;\\n            this.currentSize--;\\n        }\\n    }\\n\\n    front() {\\n        if (this.currentSize === 0) return -1;\\n        return this.arr[this.frontIdx];\\n    }\\n\\n    back() {\\n        if (this.currentSize === 0) return -1;\\n        return this.arr[this.rearIdx];\\n    }\\n\\n    size() {\\n        return this.currentSize;\\n    }\\n\\n    isEmpty() {\\n        return this.currentSize === 0;\\n    }\\n}\\n\\nfunction solve(lines) {\\n    const q = parseInt(lines[0], 10);\\n    const queue = new MyQueue();\\n    for (let i = 1; i <= q; i++) {\\n        const op = lines[i].split(' ');\\n        const cmd = op[0];\\n        if (cmd === 'push') {\\n            queue.push(parseInt(op[1], 10));\\n        } else if (cmd === 'pop') {\\n            queue.pop();\\n        } else if (cmd === 'front') {\\n            console.log(queue.front());\\n        } else if (cmd === 'back') {\\n            console.log(queue.back());\\n        } else if (cmd === 'size') {\\n            console.log(queue.size());\\n        } else if (cmd === 'isEmpty') {\\n            console.log(queue.isEmpty());\\n        }\\n    }\\n}\\n\\nconst readline = require('readline');\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\