) {\\n        return head.next;\\n    }\\n    let curr = head;\\n    // Traverse to the (k-1)th node\\n    for (let i = 0; i < k - 2; i++) {\\n        if (!curr) return head; // k is out of bounds\\n        curr = curr.next;\\n    }\\n    if (curr && curr.next) {\\n        curr.next = curr.next.next;\\n    }\\n    return head;\\n}\\n\\nconst rl = readline.createInterface({\\n    input: process.stdin,\\n    output: process.stdout,\\n    terminal: false\\n});\\n\\nlet lines = [];\\nrl.on('line', (line) => {\\n    lines.push(line);\\n});\\n\\nrl.on('close', () => {\\n    const n = parseInt(lines[0], 10);\\n    let head = null;\\n    if (n > 0) {\\n        const values = lines[1].split(' ').map(Number);\\n        let current = head = new ListNode(values[0]);\\n        for (let i = 1; i < n; i++) {\\n            current.next = new ListNode(values[i]);\\n            current = current.next;\\n        }\\n    }\\n    const k = parseInt(lines[2], 10);\\n    const resultHead = removeKthNode(head, k);\\n    const result = [];\\n    let current = resultHead;\\n    while(current) {\\n        result.push(current.val);\\n        current = current.next;\\n    }\\n    console.log(result.join(' '));\\n});"}	2025-07-31 20:23:22.127	2025-07-31 20:23:22.127	["1 <= n <= 1000", "1 <= k <= n", "1 <= element <= 1000"]	{Amazon}	\N
